from typing import Any, Optional, Dict, List

class LRUCache:
    """A fixed-capacity cache that evicts the least recently used entry."""
    def __init__(self, capacity: int):
        if capacity < 1:
            raise ValueError("Capacity must be at least 1.")
        self.capacity = capacity
        # Tracks usage order: index 0 is LRU, last index is MRU
        self.order: List[Any] = [] 
        self.cache: Dict[Any, Any] = {}

    def __len__(self) -> int:
        return len(self.cache)

    def __contains__(self, key: Any) -> bool:
        return key in self.cache

    def resize(self, capacity: int) -> List[Any]:
        """Changes the capacity, evicts LRU keys if necessary, and returns evicted keys in order."""
        if capacity < 1:
            raise ValueError("Capacity must be at least 1.")

        evicted_keys: List[Any] = []

        while len(self.cache) > capacity:
            # Evict the Least Recently Used key (at index 0 of order)
            if not self.order: # Should not happen if len(self.cache) > 0
                break 

            lru_key = self.order.pop(0)

            # Remove from cache and record eviction
            if lru_key in self.cache:
                del self.cache[lru_key]
                evicted_keys.append(lru_key)

        self.capacity = capacity
        return evicted_keys
