        if text.strip() != text:
             raise ValueError("Version string cannot contain surrounding whitespace.")
        if text.startswith('v'):
             raise ValueError("Version string cannot start with 'v'.")

        match = cls._SEMVER_REGEX.match(text)

        if not match:
            # Check for cases like missing parts (e.g., '1.2') or malformed structure
            raise ValueError(f"Invalid SemVer 2.0.0 format: {text}")

        major_str, minor_str, patch_str, prerelease_str, build_str = match.groups()

