        minor = int(minor_str)
        patch = int(patch_str)

        # Parse pre-release identifiers
        prerelease = tuple(prerelease_str.split('.')) if prerelease_str else tuple()
        if prerelease_str and not all(prerelease):
             raise ValueError("SemVer pre-release identifiers cannot be empty.")

        # Parse build identifiers
        build = tuple(build_str.split('.')) if build_str else tuple()
        if build_str and not all(build):
             raise ValueError("SemVer build identifiers cannot be empty.")

        return cls(major, minor, patch, prerelease, build, text)

