        return Fraction(self.value)

class BinaryOpNode(ASTNode):
    def __init__(self, op: str, left: ASTNode, right: ASTNode, position: int):
        self.op = op
        self.left = left
        self.right = right
        self.position = position

    def evaluate(self) -> Fraction:
        left_val = self.left.evaluate()
        right_val = self.right.evaluate()

        if self.op == '+':
            return left_val + right_val
        elif self.op == '-':
            return left_val - right_val
        elif self.op == '*':
            return left_val * right_val
        elif self.op == '/':
            if right_val == 0:
                # Division by zero: use the position of the '/' operator
                raise CalcError("Division by zero", self.position)
            return left_val / right_val
        raise RuntimeError(f"Unknown operator: {self.op}")

class UnaryOpNode(ASTNode):
    def __init__(self, op: str, child: ASTNode, position: int):
        self.op = op
        self.child = child
        self.position = position

    def evaluate(self) -> Fraction:
        child_val = self.child.evaluate()
        if self.op == '-':
            return -child_val
        raise RuntimeError(f"Unknown unary operator: {self.op}")

# --- Parser Implementation (Recursive Descent) ---
class Parser:
    def __init__(self, tokens: list[Token]):
        self.tokens = tokens
        self.pos = 0

    def peek(self) -> Token | None:
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return None

    def consume(self, expected_type: str = None, expected_value: str = None) -> Token:
        token = self.peek()
        if token is None:
            # Fallback error for unexpected end of expression during consumption
            last_token_start = self.tokens[-1].start if self.tokens else 0
            raise CalcError("Unexpected end of expression", len(self.tokens[-1].value) if self.tokens else 0)

        if expected_type and token.type != expected_type:
            raise CalcError(f"Expected token type {expected_type}, but got {token.type} ('{token.value}')", token.start)
        if expected_value and token.value != expected_value:
            raise CalcError(f"Expected token value '{expected_value}', but got '{token.value}'", token.start)

        self.pos += 1
        return token

    def parse(self) -> ASTNode:
        # Start parsing at the lowest precedence level: Expression (handles + and -)
        node = self.parse_expression()

        # Syntax Check: Must consume all tokens
        if self.peek() is not None:
            # The error position is the start of the token that remains unconsumed.
            remaining_token = self.peek()
            raise CalcError(f"Unexpected token '{remaining_token.value}'", remaining_token.start)

        return node

    # Grammar rules based on precedence (Low to High)

    def parse_expression(self) -> ASTNode:
        # Handles addition and subtraction (Left Associative)
        node = self.parse_term()

        while True:
            token = self.peek()
            if token and token.type == 'OP' and token.value in ('+', '-'):
                op = token.value
                self.consume('OP', op)
                right = self.parse_term()
                # Create binary operation node, using the operator's position for error reporting
                node = BinaryOpNode(op, node, right, token.start)
            else:
                break
        return node

    def parse_term(self) -> ASTNode:
        # Handles multiplication and division (Left Associative)
        node = self.parse_factor()

        while True:
            token = self.peek()
            if token and token.type == 'OP' and token.value in ('*', '/'):
                op = token.value
                self.consume('OP', op)
                right = self.parse_factor()
                # Create binary operation node
                node = BinaryOpNode(op, node, right, token.start)
            else:
                break
        return node

    def parse_factor(self) -> ASTNode:
        # Handles numbers, unary minus, and parentheses
        token = self.peek()
        if not token:
            raise CalcError("Unexpected end of expression: Expected operand", len(self.tokens[0].value) if self.tokens else 0)

        # Handle Unary Minus first
        if token.type == 'UNARY_MINUS':
            op_token = self.consume('UNARY_MINUS')
            # Recursively parse the factor that follows the unary minus
            child = self.parse_factor()
            return UnaryOpNode('-', child, op_token.start)

        # Handle Parentheses
        elif token.type == 'LPAREN':
            self.consume('LPAREN')
            # Parse the subexpression inside the parentheses
            node = self.parse_expression()
            # Check for closing parenthesis
            self.consume('RPAREN')
            return node

        # Handle Numbers
        elif token.type == 'NUMBER':
            token = self.consume('NUMBER')
            return NumberNode(token.value, token.start)

        # Syntax Error: If we reached here, the token was not a valid start of a factor
        else:
            # Report error at the position of the invalid token
            raise CalcError(f"Syntax error: Unexpected token {token.type} ('{token.value}')", token.start)

# --- Main Entry Point ---
def evaluate(expr: str) -> Fraction:
    """Evaluates an arithmetic expression exactly and reports errors with their position."""
    if not expr.strip():
        return Fraction(0) # Per requirement for '' -> 0

    # 1. Tokenize
    tokenizer = Tokenizer(expr)
    tokens = tokenizer.tokenize()

    # 2. Parse and Build AST
    parser = Parser(tokens)
    ast_root = parser.parse()

    # 3. Evaluate AST
    return ast_root.evaluate()


