import re
from fractions import Fraction
from typing import Optional, Dict, Any

class CalcError(Exception):
    """Custom exception for calculator errors, including position tracking."""
    def __init__(self, message: str, position: Optional[int] = None):
        super().__init__(message)
        self.position = position

    def __str__(self):
        if self.position is not None:
            return f"CalcError: {super().__str__()} at position {self.position}"
        return super().__str__()


# --- Token Definition and Lexer ---

# A name is a letter or _ followed by letters, digits or _
NAME_PATTERN = r'([a-zA-Z_][a-zA-Z0-9_]*)'

TOKEN_SPECIFICATION = [
    # Exponentiation must be checked before general operators if it overlaps
    ('OP_POW', r'\*\*'), 
    ('NUMBER', r'([0-9]+(\.[0-9]*)?|\b\.[0-9]+)'), 
    ('NAME', NAME_PATTERN), # Variables and Functions
    ('OP_UNARY_MINUS', r'^-'), 
    ('OP_PLUS', r'\+'),
    ('OP_MINUS', r'-'),
    ('OP_MUL', r'\*'),
    ('OP_DIV', r'\/'),
    ('LPAREN', r'\('),
    ('RPAREN', r'\)'),
    ('COMMA', r','), # New token for function arguments
    ('SKIP', r'[ \t]+')
]

# Compile regex for efficiency
TOKEN_REGEX = '|'.join(f'(?P<{name}>{pattern})' for name, pattern in TOKEN_SPECIFICATION)

class Token:
    """Represents a single recognized token in the expression."""
    def __init__(self, type: str, value: str, start: int, end: int):
        self.type = type
        self.value = value
        self.start = start
        self.end = end

    def __repr__(self):
        return f"Token({self.type}, {repr(self.value)}, pos=[{self.start}, {self.end}])"

def tokenize(expr: str) -> list[Token]:
    """Lexical analysis of the expression string."""
    tokens = []
    pos = 0

    for mo in re.finditer(TOKEN_REGEX, expr):
        kind = mo.lastgroup
        value = mo.group(kind)
        start = mo.start()
        end = mo.end()

        if kind == 'SKIP':
            continue
        elif kind == 'NUMBER':
            num_str = value.strip()
            tokens.append(Token('NUMBER', num_str, start, end))
        elif kind == 'NAME':
            tokens.append(Token('NAME', value, start, end))
        elif kind == 'OP_POW':
            tokens.append(Token('OP_POW', '**', start, end))
        elif kind == 'OP_UNARY_MINUS':
            tokens.append(Token('OP_UNARY_MINUS', '-', start, end))
        elif kind == 'OP_PLUS':
            tokens.append(Token('OP_PLUS', '+', start, end))
        elif kind == 'OP_MINUS':
            tokens.append(Token('OP_MINUS', '-', start, end))
        elif kind == 'OP_MUL':
            tokens.append(Token('OP_MUL', '*', start, end))
        elif kind == 'OP_DIV':
            tokens.append(Token('OP_DIV', '/', start, end))
        elif kind == 'LPAREN':
            tokens.append(Token('LPAREN', '(', start, end))
        elif kind == 'RPAREN':
            tokens.append(Token('RPAREN', ')', start, end))
        elif kind == 'COMMA':
            tokens.append(Token('COMMA', ',', start, end))
        else:
            # Should not happen
            pass

        pos = end

    # Check for remaining unparsed characters
    if pos < len(expr):
        unparsed_char_pos = pos
        # Skip trailing whitespace to find the real error start
        while unparsed_char_pos < len(expr) and expr[unparsed_char_pos].isspace():
             unparsed_char_pos += 1

        if unparsed_char_pos < len(expr):
            raise CalcError("Syntax error: Unexpected character", unparsed_char_pos)

    return tokens


# --- AST Node Definitions ---

class ExpressionNode:
    """Base class for nodes in the expression tree."""
    def evaluate(self) -> Fraction:
        raise NotImplementedError("Must implement evaluate method")

class NumberNode(ExpressionNode):
    def __init__(self, value: Fraction, start: int, end: int):
        self.value = value
        self.start = start
        self.end = end

    def evaluate(self) -> Fraction:
        return self.value

class VariableNode(ExpressionNode):
    """Represents a variable lookup."""
    def __init__(self, name: str, start: int, end: int):
        self.name = name
        self.start = start
        self.end = end

    def evaluate(self, variables: Optional[Dict[str, Any]]) -> Fraction:
        if variables is None:
            raise CalcError(f"Unknown variable '{self.name}'", self.start)
        if self.name not in variables:
            raise CalcError(f"Unknown variable '{self.name}'", self.start)

        val = variables[self.name]
        if isinstance(val, int):
            return Fraction(val)
        if isinstance(val, Fraction):
            return val
        # This should technically not happen if usage adheres to spec
        raise CalcError(f"Variable '{self.name}' must be int or Fraction", self.start)

class BinaryOpNode(ExpressionNode):
    def __init__(self, left: ExpressionNode, op: str, right: ExpressionNode, op_start: int):
        self.left = left
        self.op = op
        self.right = right
        self.op_start = op_start

    def evaluate(self, variables: Optional[Dict[str, Any]]) -> Fraction:
        left_val = self.left.evaluate(variables)
        right_val = self.right.evaluate(variables)

        if self.op == '+':
            return left_val + right_val
        elif self.op == '-':
            return left_val - right_val
        elif self.op == '*':
            return left_val * right_val
        elif self.op == '/':
            if right_val == 0:
                raise CalcError("Division by zero", self.op_start)
            return left_val / right_val
        elif self.op == '**':
            # Exponentiation logic
            if right_val < 0:
                if left_val == 0:
                    raise CalcError("Division by zero: 0 raised to a negative power", self.op_start)

                # Check if exponent is a whole number (i.e., its numerator is divisible by its denominator)
                if right_val.denominator != 1:
                    raise CalcError("Exponent must be a whole number", self.op_start)

            # If right_val is fractional and not an integer, it's an error.
            if right_val.denominator != 1:
                 raise CalcError("Exponent must be a whole number", self.op_start)

            # Safe to calculate since right_val is an integer
            exponent = right_val.numerator
            if exponent < 0: # Already checked for 0^neg case, but re-checking safety
                 return Fraction(1, left_val**(-exponent)) # Equivalent to 1 / (left_val ^ |exp|)
            else:
                 return left_val ** exponent

        raise CalcError("Unknown binary operator", self.op_start)

class UnaryOpNode(ExpressionNode):
    def __init__(self, operand: ExpressionNode, op_start: int):
        self.operand = operand
        self.op_start = op_start

    def evaluate(self, variables: Optional[Dict[str, Any]]) -> Fraction:
        operand_val = self.operand.evaluate(variables)
        if self.op == 'UNARY_MINUS':
            return -operand_val
        raise CalcError("Unknown unary operator", self.op_start)

class FunctionCallNode(ExpressionNode):
    def __init__(self, func_name: str, args: list[ExpressionNode], start: int):
        self.func_name = func_name
        self.args = args
        self.start = start

    def evaluate(self, variables: Optional[Dict[str, Any]]) -> Fraction:
        arg_values = [arg.evaluate(variables) for arg in self.args]

        if self.func_name == 'abs':
            if len(arg_values) != 1:
                raise CalcError("abs() takes exactly one argument", self.start)
            # abs requires converting Fraction to float to use standard abs, then back if possible, 
            # but since we must maintain exactness, we use math.fabs if we had math, otherwise we rely on properties.
            # For Fraction, abs(x) = |x| which is just max(x, -x).
            return max(arg_values[0], -arg_values[0])

        elif self.func_name == 'min':
            if not arg_values:
                raise CalcError("min() requires one or more arguments", self.start)
            return min(arg_values)

        elif self.func_name == 'max':
            if not arg_values:
                raise CalcError("max() requires one or more arguments", self.start)
            return max(arg_values)

        raise CalcError(f"Unknown function '{self.func_name}'", self.start)

# --- Parser Implementation (Recursive Descent/Operator Precedence) ---

class Parser:
    """Handles parsing tokens into an Abstract Syntax Tree (AST)."""
    def __init__(self, tokens: list[Token]):
        self.tokens = tokens
        self.pos = 0

    def current_token(self) -> Optional[Token]:
        return self.tokens[self.pos] if self.pos < len(self.tokens) else None

    def consume(self, expected_type: Optional[str] = None, expected_value: Optional[str] = None) -> Token:
        token = self.current_token()
        if not token:
            # This is an EOF error, use a large position or indicate EOF
            raise CalcError("Syntax error: Unexpected end of expression", len(self.tokens) * 100)

        if expected_type and token.type != expected_type:
            raise CalcError(f"Syntax error: Expected {expected_type}, got {token.type}", token.start)
        if expected_value and token.value != expected_value:
            raise CalcError(f"Syntax error: Expected '{expected_value}', got '{token.value}'", token.start)

        self.pos += 1
        return token

    def parse(self) -> ExpressionNode:
        node = self._parse_expression()

        if self.current_token() is not None:
            token = self.current_token()
            # Check for trailing tokens (e.g., '1 2' or '1 +')
            raise CalcError("Syntax error: Unexpected token at end of expression", token.start)

        return node

    # Grammar precedence (Highest to Lowest):
    # 1. Primary (Number, Variable, FunctionCall, Parentheses)
    # 2. UnaryOp (Unary Minus)
    # 3. Power (**) (Right Associative)
    # 4. Mul/Div (*, /) (Left Associative)
    # 5. Add/Sub (+, -) (Left Associative)

    def _parse_expression(self) -> ExpressionNode: # Handles + and -
        node = self._parse_term()

        while self.current_token() and self.current_token().type in ['OP_PLUS', 'OP_MINUS']:
            op_token = self.consume()
            right = self._parse_term()
            node = BinaryOpNode(node, op_token.value, right, op_token.start)
        return node

    def _parse_term(self) -> ExpressionNode: # Handles ** (Right Associative)
        node = self._parse_unary()

        while self.current_token() and self.current_token().type == 'OP_POW':
            op_token = self.consume()
            # Crucial: For right associativity, we recursively call _parse_term again
            # This ensures 2 ** 3 ** 2 groups as 2 ** (3 ** 2)
            right = self._parse_term()
            node = BinaryOpNode(node, op_token.value, right, op_token.start)
        return node

    def _parse_unary(self) -> ExpressionNode: # Handles unary minus
        token = self.current_token()
        if token and token.type == 'OP_UNARY_MINUS':
            op_token = self.consume()
            # Recursively parse what follows the unary minus
            operand = self._parse_unary() # Allow chained unary minus (--4)
            return UnaryOpNode(operand, op_token.start)

        return self._parse_primary()

    def _parse_primary(self) -> ExpressionNode:
        token = self.current_token()

        if not token:
            raise CalcError("Syntax error: Empty expression", 0)

        if token.type == 'NUMBER':
            self.consume('NUMBER')
            value = Fraction(token.value)
            return NumberNode(value, token.start, token.end)

        elif token.type == 'NAME':
            name_token = self.consume('NAME')
            next_token = self.current_token()

            if next_token and next_token.type == 'LPAREN':
                # This is a function call
                func_name = name_token.value
                self.consume('LPAREN')

                args = []
                # Parse arguments until ')' or EOF (which is caught later)
                if self.current_token() and self.current_token().type != 'RPAREN':
                    # Parse first argument
                    args.append(self._parse_expression())

                    # Parse subsequent arguments
                    while self.current_token() and self.current_token().type == 'COMMA':
                        self.consume('COMMA')
                        args.append(self._parse_expression())

                self.consume('RPAREN')
                return FunctionCallNode(func_name, args, name_token.start)
            else:
                # This is a variable
                return VariableNode(name_token.value, name_token.start, name_token.end)

        elif token.type == 'LPAREN':
            self.consume('LPAREN')
            node = self._parse_expression() # Recurse to the lowest level inside parens
            self.consume('RPAREN') # Expect closing parenthesis
            return node

        else:
            # Any other token is a syntax error here (e.g., operator at start)
            raise CalcError("Syntax error: Unexpected token", token.start)


# --- Main Evaluation Function ---

def evaluate(expr: str, variables: Optional[Dict[str, Any]] = None) -> Fraction:
    """Evaluates an arithmetic expression string exactly, supporting variables and functions.

    Args:
        expr: The expression string.
        variables: A mapping from names to values (int or Fraction).

    Returns: The result as a Fraction.

    Raises: CalcError for any syntax or runtime arithmetic error.
    """
    if not expr.strip():
        raise CalcError("Input expression cannot be empty", 0)

    # 1. Tokenize
    tokens = tokenize(expr)

    # 2. Parse
    parser = Parser(tokens)
    ast_root = parser.parse()

    # 3. Evaluate
    return ast_root.evaluate(variables)


