# Regex for names/identifiers: letter or '_' followed by letter, digit, or '_'
NAME_PATTERN = r'[a-zA-Z_][a-zA-Z0-9_]*'

TOKEN_SPECIFICATION = [
    # Numbers: Handles integers and fractions (e.g., 1, 1.0, .5)
    ('NUMBER', r'([0-9]+(\.[0-9]*)?|\.[0-9]+)'),
    # Names/Identifiers
    ('NAME', NAME_PATTERN),
    # Operators
    ('OP_UNARY_MINUS', r'^-'),
    ('OP_PLUS', r'\+'),
    ('OP_MINUS', r'-'),
    ('OP_MUL', r'\*'),
    ('OP_DIV', r'\/'),
    # Grouping
    ('LPAREN', r'\('),
    ('RPAREN', r'\)'),
    # Whitespace to skip
    ('SKIP', r'[ \t]+')
]

# Compile regex for efficiency
TOKEN_REGEX = '|'.join(f'(?P<{name}>{pattern})' for name, pattern in TOKEN_SPECIFICATION)

class Token:
    """Represents a single recognized token in the expression."""
    def __init__(self, type: str, value: str, start: int, end: int):
        self.type = type
        self.value = value
        self.start = start
        self.end = end

    def __repr__(self):
        return f"Token({self.type}, '{self.value}', pos=[{self.start}, {self.end}])"

def tokenize(expr: str) -> list[Token]:
    """Lexical analysis of the expression string."""
    tokens = []

    for mo in re.finditer(TOKEN_REGEX, expr):
        kind = mo.lastgroup
        value = mo.group(kind)
        start = mo.start()
        end = mo.end()

        if kind == 'SKIP':
            continue

        # Special handling for potential float parsing issues in regex match
        if kind == 'NUMBER':
            # Ensure that if it looks like a number but is part of a larger string (e.g., '1.5a'), 
            # it's caught by the error checking later, but here we just parse it.
            tokens.append(Token('NUMBER', value, start, end))
        elif kind == 'NAME':
            tokens.append(Token('NAME', value, start, end))
        elif kind == 'OP_UNARY_MINUS':
            tokens.append(Token('OP_UNARY_MINUS', '-', start, end))
        elif kind == 'OP_PLUS':
            tokens.append(Token('OP_PLUS', '+', start, end))
        elif kind == 'OP_MINUS':
            tokens.append(Token('OP_MINUS', '-', start, end))
        elif kind == 'OP_MUL':
            tokens.append(Token('OP_MUL', '*', start, end))
        elif kind == 'OP_DIV':
            tokens.append(Token('OP_DIV', '/', start, end))
        elif kind == 'LPAREN':
            tokens.append(Token('LPAREN', '(', start, end))
        elif kind == 'RPAREN':
            tokens.append(Token('RPAREN', ')', start, end))
        # Other tokens are ignored if they don't match a pattern

    # Check for remaining unparsed characters
    current_pos = sum(t.end for t in tokens) if tokens else 0

    # This check is imperfect because regex might skip over illegal sequences.
    # A more robust check would involve iterating over the string and ensuring every char is consumed.
    # For this scope, we rely on the parser to catch unparsed tokens if they aren't consumed.

    return tokens


