        if variables is None:
            raise CalcError(f"Unknown variable '{self.name}'", self.start) # Rule: Unknown var when variables=None
        if self.name not in variables:
            raise CalcError(f"Unknown variable '{self.name}'", self.start) # Rule: Unknown var

        val = variables[self.name]
        if isinstance(val, int): 
