## Implement Built-in Functions

import re
from fractions import Fraction
from typing import Dict, Optional, List

class CalcError(Exception):
    """Custom exception for calculator errors, including position tracking."""
    def __init__(self, message, position=None):
        super().__init__(message)
        self.position = position

    def __str__(self):
        if self.position is not None:
            return f"CalcError: {super().__str__()} at position {self.position}"
        return super().__str__()


# --- Token Definition and Lexer ---

# Name regex: letter or _ followed by letters, digits, or _
NAME_REGEX = r'[a-zA-Z_][a-zA-Z0-9_]*'

TOKEN_SPECIFICATION = [ 
    # NUMBER must come before NAME to avoid matching '1' as part of a name if we allowed leading digits
    ('NUMBER', r'([0-9]+(\.[0-9]*)?|\.[0-9]+)'), 
    # NEW: Name/Identifier
    ('NAME', NAME_REGEX),
    ('OP_UNARY_MINUS', r'^-'), 
    ('OP_PLUS', r'\+'),
    ('OP_MINUS', r'-'),
    ('OP_MUL', r'\*'),
    ('OP_DIV', r'\/'),
    ('LPAREN', r'\('),
    ('RPAREN', r'\)'),
    # NEW: Comma for arguments
    ('COMMA', r','),
    ('SKIP', r'[ \t]+')
]

# Compile regex for efficiency
TOKEN_REGEX = '|'.join(f'(?P<{name}>{pattern})' for name, pattern in TOKEN_SPECIFICATION)

class Token:
    """Represents a single recognized token in the expression."""
    def __init__(self, type, value, start, end):
        self.type = type
        self.value = value
        self.start = start
        self.end = end

    def __repr__(self):
        return f"Token({self.type}, {repr(self.value)}, pos=[{self.start}, {self.end}])"

def tokenize(expr: str) -> list[Token]:
    """Lexical analysis of the expression string."""
    tokens = []
    pos = 0

    for mo in re.finditer(TOKEN_REGEX, expr):
        kind = mo.lastgroup
        value = mo.group(kind)
        start = mo.start()
        end = mo.end()

        if kind == 'SKIP':
            continue
        elif kind == 'NUMBER':
            # Normalize numbers
            tokens.append(Token('NUMBER', value, start, end))
        elif kind == 'NAME':
            tokens.append(Token('NAME', value, start, end))
        elif kind == 'OP_UNARY_MINUS':
            tokens.append(Token('OP_UNARY_MINUS', '-', start, end))
        elif kind == 'OP_PLUS':
            tokens.append(Token('OP_PLUS', '+', start, end))
        elif kind == 'OP_MINUS':
            tokens.append(Token('OP_MINUS', '-', start, end))
        elif kind == 'OP_MUL':
            tokens.append(Token('OP_MUL', '*', start, end))
        elif kind == 'OP_DIV':
            tokens.append(Token('OP_DIV', '/', start, end))
        elif kind == 'LPAREN':
            tokens.append(Token('LPAREN', '(', start, end))
        elif kind == 'RPAREN':
            tokens.append(Token('RPAREN', ')', start, end))
        elif kind == 'COMMA':
            tokens.append(Token('COMMA', ',', start, end))
        else:
            pass

        pos = end

    # Check for remaining unparsed characters
    if pos < len(expr):
        unparsed_char_pos = pos
        while unparsed_char_pos < len(expr) and expr[unparsed_char_pos].isspace():
            unparsed_char_pos += 1

        if unparsed_char_pos < len(expr):
            raise CalcError("Syntax error: Unexpected character", unparsed_char_pos)

    return tokens


# --- Parser / Shunting-Yard Inspired Logic (AST Construction / Evaluation) ---

# Precedence map: lower number means lower precedence (evaluated later)
PRECEDENCE = {
    'UNARY_MINUS': 4,  # Highest precedence
    '*': 3,
    '/': 3,
    '+': 2,
    '-': 2
}

# Associativity: True for left, False for right. All binary ops are left-associative.
ASSOCIATIVITY = {
    '*': True,
    '/': True,
    '+': True,
    '-': True
}

class ExpressionNode:
    """Base class for nodes in the expression tree."""
    pass

class NumberNode(ExpressionNode):
    def __init__(self, value: Fraction, start: int, end: int):
        self.value = value
        self.start = start
        self.end = end

    def evaluate(self) -> Fraction:
        return self.value

class BinaryOpNode(ExpressionNode):
    def __init__(self, left: ExpressionNode, op: str, right: ExpressionNode, op_start: int):
        self.left = left
        self.op = op
        self.right = right
        self.op_start = op_start

    def evaluate(self) -> Fraction:
        left_val = self.left.evaluate()
        right_val = self.right.evaluate()

        if self.op == '/' and right_val == 0:
            raise CalcError("Division by zero", self.op_start)

        if self.op == '+':
            return left_val + right_val
        elif self.op == '-':
            return left_val - right_val
        elif self.op == '*':
            return left_val * right_val
        elif self.op == '/':
            return left_val / right_val
        raise CalcError("Unknown binary operator", self.op_start)

class UnaryOpNode(ExpressionNode):
    def __init__(self, operand: ExpressionNode, op_start: int):
        self.operand = operand
        self.op_start = op_start

    def evaluate(self) -> Fraction:
        operand_val = self.operand.evaluate()
        if self.op == 'UNARY_MINUS':
            return -operand_val
        raise CalcError("Unknown unary operator", self.op_start)

class VariableNode(ExpressionNode):
    """Represents a named variable."""
    def __init__(self, name: str, start: int, end: int):
        self.name = name
        self.start = start
        self.end = end

    def evaluate(self, variables: Optional[Dict[str, Fraction]]) -> Fraction:
        if variables is None:
            # This should ideally be caught by the caller if variables=None is passed to evaluate
            raise CalcError(f"Unknown variable: {self.name} (variables not provided)", self.start)

        if self.name not in variables:
            raise CalcError(f"Unknown variable: {self.name}", self.start)

        value = variables[self.name]
        # Check type safety (variables must be int or Fraction)
        if not isinstance(value, (int, Fraction)): 
             # This case should ideally not happen if input validation is perfect, but safe to check
             raise CalcError(f"Variable {self.name} must be an integer or Fraction.", self.start)
        return value

class FunctionCallNode(ExpressionNode):
    """Represents a function call (e.g., abs(x), min(a, b))."""
    def __init__(self, name: str, args: List[ExpressionNode], name_start: int):
        self.name = name
        self.args = args
        self.name_start = name_start

    def evaluate(self, variables: Optional[Dict[str, Fraction]]) -> Fraction:
        # 1. Validate function existence and argument count
        if self.name == 'abs':
            if len(self.args) != 1:
                raise CalcError(f"Function abs requires exactly 1 argument, got {len(self.args)}", self.name_start)
        elif self.name in ('min', 'max'):
            if len(self.args) < 1:
                raise CalcError(f"Function {self.name} requires at least 1 argument, got {len(self.args)}", self.name_start)
        elif self.name not in ('abs', 'min', 'max'):
            raise CalcError(f"Unknown function: {self.name}", self.name_start)

        # 2. Evaluate arguments
        evaluated_args = []
        for arg_node in self.args:
            evaluated_args.append(arg_node.evaluate(variables))

        # 3. Apply specific logic
        if self.name == 'abs':
            return abs(evaluated_args[0])
        elif self.name == 'min':
            return min(evaluated_args)
        elif self.name == 'max':
            return max(evaluated_args)

        # Should be unreachable
        raise CalcError("Internal Function Logic Error", self.name_start)


# --- Parser Implementation (Recursive Descent/Operator Precedence) ---

class Parser:
    """Handles parsing tokens into an Abstract Syntax Tree (AST)."""
    def __init__(self, tokens: list[Token], variables: Optional[Dict[str, Fraction]]):
        self.tokens = tokens
        self.pos = 0
        self.variables = variables

    def current_token(self) -> Token | None:
        return self.tokens[self.pos] if self.pos < len(self.tokens) else None

    def consume(self, expected_type: str = None, expected_value: str = None) -> Token:
        token = self.current_token()
        if not token:
            raise CalcError("Syntax error: Unexpected end of expression", len(self.tokens) * 100) # Placeholder for EOF error

        if expected_type and token.type != expected_type:
            raise CalcError(f"Syntax error: Expected {expected_type}, got {token.type}", token.start)
        if expected_value and token.value != expected_value:
            raise CalcError(f"Syntax error: Expected '{expected_value}', got '{token.value}'", token.start)

        self.pos += 1
        return token

    def parse(self) -> ExpressionNode:
        node = self._parse_terms()

        if self.current_token() is not None:
            token = self.current_token()
            if token.type not in ['RPAREN']: 
                 raise CalcError("Syntax error: Unexpected token at end of expression", token.start)

        return node

    def _parse_terms(self) -> ExpressionNode: # Handles + and -
        node = self._parse_factor()

        while self.current_token() and self.current_token().type in ['OP_PLUS', 'OP_MINUS']:
            op_token = self.consume()
            right = self._parse_factor()
            node = BinaryOpNode(node, op_token.value, right, op_token.start)
        return node

    def _parse_factor(self) -> ExpressionNode: # Handles * and / (Multiplication/Division)
        node = self._parse_unary()

        while self.current_token() and self.current_token().type in ['OP_MUL', 'OP_DIV']:
            op_token = self.consume()
            right = self._parse_unary()
            node = BinaryOpNode(node, op_token.value, right, op_token.start)
        return node

    def _parse_unary(self) -> ExpressionNode: # Handles unary minus
        token = self.current_token()
        if token and token.type == 'OP_UNARY_MINUS':
            op_token = self.consume()
            operand = self._parse_unary() # Allow chained unary minus (--4)
            return UnaryOpNode(operand, op_token.start)

        return self._parse_primary()

    def _parse_primary(self) -> ExpressionNode:
        token = self.current_token()

        if not token:
            raise CalcError("Syntax error: Empty expression", 0)

        # 1. Number
        if token.type == 'NUMBER':
            self.consume('NUMBER')
            value = Fraction(token.value)
            return NumberNode(value, token.start, token.end)

        # 2. Function Call
        elif token.type == 'NAME':
            name_token = self.consume('NAME')

            # Check if it's a function call: Name followed by ( (ignoring whitespace)
            next_token = self.current_token()
            if next_token and next_token.type == 'LPAREN':
                func_name = name_token.value
                # Consume '('
                self.consume('LPAREN')

                args: List[ExpressionNode] = []
                # Parse arguments until ')'
                while self.current_token() and self.current_token().type != 'RPAREN':
                    # Parse argument expression
                    arg_node = self._parse_terms() # Arguments can contain +, -
                    args.append(arg_node)

                    # Check for comma separator, unless it's the last argument (which is implicitly handled by the loop condition)
                    next_tok_after_arg = self.current_token()
                    if next_tok_after_arg and next_tok_after_arg.type == 'COMMA':
                        self.consume('COMMA')
                    # If we hit RPAREN or end of tokens without a comma, the loop terminates correctly.
                    elif next_tok_after_arg is None:
                         raise CalcError("Syntax error: Expected ')' after argument", name_token.start)

                self.consume('RPAREN')
                return FunctionCallNode(func_name, args, name_token.start)

            # 3. Variable Reference
            else:
                self.consume('NAME')
                return VariableNode(name_token.value, name_token.start, name_token.end)

        # 4. Parentheses
        elif token.type == 'LPAREN':
            self.consume('LPAREN')
            node = self._parse_terms() # Recurse to the lowest level inside parens
            self.consume('RPAREN') # Expect closing parenthesis
            return node

        else:
            # Any other token is a syntax error here
            raise CalcError("Syntax error: Unexpected token", token.start)


# --- Main Evaluation Function ---

def evaluate(expr: str, variables: Optional[Dict[str, Fraction]] = None) -> Fraction:
    """Evaluates an arithmetic expression string exactly, supporting variables and functions.

    Signature: evaluate(expr: str, variables: Optional[Dict[str, Fraction]]) -> Fraction.

    Raises CalcError for any syntax or runtime arithmetic error.
    """
    if not expr.strip():
        raise CalcError("Input expression cannot be empty", 0)

    # 1. Tokenize
    tokens = tokenize(expr)

    # 2. Parse
