import re
from fractions import Fraction

class CalcError(Exception):
    """Custom exception for arithmetic calculation errors with position tracking."""
    def __init__(self, message: str, position: int):
        super().__init__(message)
        self.position = position

    def __str__(self):
        return f"CalcError at position {self.position}: {self.args[0]}"


class Token:
    """Represents a single token in the expression."""
    def __init__(self, type: str, value: str, start: int):
        self.type = type  # e.g., 'NUMBER', 'OP', 'LPAREN', 'UNARY_MINUS'
        self.value = value
        self.start = start

    def __repr__(self):
        return f"Token({self.type}, '{self.value}', start={self.start})"


class Tokenizer:
    """Tokenizes an arithmetic expression, identifying basic syntax errors."""
    def __init__(self, expr: str):
        self.expr = expr
        self.pos = 0

    def _skip_whitespace(self):
        """Advances position past any whitespace."""
        while self.pos < len(self.expr) and self.expr[self.pos].isspace():
            self.pos += 1

    def tokenize(self) -> list[Token]:
        """Yields tokens for the given expression, raising CalcError on syntax failure."""
        tokens = []
        while self.pos < len(self.expr):
            self._skip_whitespace()
            if self.pos >= len(self.expr):
                break

            char = self.expr[self.pos]
            start_pos = self.pos

            if char in ('+', '-', '*', '/'):
                # Check for potential unary minus
                is_start_of_expression = (len(tokens) == 0)
                is_after_open_paren = (tokens and tokens[-1].type == 'LPAREN')
                # Binary operators are 'OP' type. Unary minus can follow another unary minus.
                is_after_operator = (tokens and tokens[-1].type in ('OP', 'UNARY_MINUS'))

                if char == '-' and (is_start_of_expression or is_after_open_paren or is_after_operator):
                    tokens.append(Token('UNARY_MINUS', '-', start_pos))
                    self.pos += 1
                    continue

                # Binary operator
                tokens.append(Token('OP', char, start_pos))
                self.pos += 1
                continue

            elif char == '(': 
                tokens.append(Token('LPAREN', char, start_pos))
                self.pos += 1
                continue

            elif char == ')': 
                tokens.append(Token('RPAREN', char, start_pos))
                self.pos += 1
                continue

            # Handle Numbers (Decimal format)
            elif char.isdigit() or char == '.':
                number_str = ''
                dot_count = 0
                current_start = self.pos

                # Greedily consume digits and dots
                while self.pos < len(self.expr) and (self.expr[self.pos].isdigit() or self.expr[self.pos] == '.'):
                    if self.expr[self.pos] == '.':
                        dot_count += 1
                    number_str += self.expr[self.pos]
                    self.pos += 1

                # Validation based on rules:
                is_valid_number = False
                if dot_count == 0:
                    if number_str.isdigit() and len(number_str) > 0:
                        is_valid_number = True
                elif dot_count == 1:
                    # Must not start or end with '.' AND must have digits on both sides
                    if not number_str.startswith('.') and not number_str.endswith('.'):
                        parts = number_str.split('.')
                        if parts[0].isdigit() and parts[1].isdigit() and len(parts[0]) > 0 and len(parts[1]) > 0:
                            is_valid_number = True

                if is_valid_number:
                    tokens.append(Token('NUMBER', number_str, current_start))
                    continue
                else:
                    # If the sequence we parsed isn't a valid number, report error at the start.
                    raise CalcError("Invalid number format", current_start)

            # Invalid character
            else:
                # This character cannot start any valid token
                raise CalcError(f"Invalid character: {char}", start_pos)

        return tokens

# --- AST Structure ---
class ASTNode:
    def evaluate(self) -> Fraction:
        raise NotImplementedError

class NumberNode(ASTNode):
    def __init__(self, value: str, position: int):
        self.value = value
        self.position = position

    def evaluate(self) -> Fraction:
        return Fraction(self.value)

class BinaryOpNode(ASTNode):
    def __init__(self, op: str, left: ASTNode, right: ASTNode, position: int):
        self.op = op
        self.left = left
        self.right = right
        self.position = position

    def evaluate(self) -> Fraction:
        left_val = self.left.evaluate()
        right_val = self.right.evaluate()

        if self.op == '+':
            return left_val + right_val
        elif self.op == '-':
            return left_val - right_val
        elif self.op == '*':
            return left_val * right_val
        elif self.op == '/':
            if right_val == 0:
                # Division by zero: use the position of the '/' operator
                raise CalcError("Division by zero", self.position)
            return left_val / right_val
        raise RuntimeError(f"Unknown operator: {self.op}")

class UnaryOpNode(ASTNode):
    def __init__(self, op: str, child: ASTNode, position: int):
        self.op = op
        self.child = child
        self.position = position

    def evaluate(self) -> Fraction:
        child_val = self.child.evaluate()
        if self.op == '-':
            return -child_val
        raise RuntimeError(f"Unknown unary operator: {self.op}")

# --- Parser Implementation (Recursive Descent) ---
class Parser:
    def __init__(self, tokens: list[Token]):
        self.tokens = tokens
        self.pos = 0

    def peek(self) -> Token | None:
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return None

    def consume(self, expected_type: str = None, expected_value: str = None) -> Token:
        token = self.peek()
        if token is None:
            # Fallback error for unexpected end of expression during consumption
            last_token_start = self.tokens[-1].start if self.tokens else 0
            raise CalcError("Unexpected end of expression", len(self.tokens[-1].value) if self.tokens else 0)

        if expected_type and token.type != expected_type:
            raise CalcError(f"Expected token type {expected_type}, but got {token.type} ('{token.value}')", token.start)
        if expected_value and token.value != expected_value:
            raise CalcError(f"Expected token value '{expected_value}', but got '{token.value}'", token.start)

        self.pos += 1
        return token

    def parse(self) -> ASTNode:
        # Start parsing at the lowest precedence level: Expression (handles + and -)
        node = self.parse_expression()

        # Syntax Check: Must consume all tokens
        if self.peek() is not None:
            # The error position is the start of the token that remains unconsumed.
            remaining_token = self.peek()
            raise CalcError(f"Unexpected token '{remaining_token.value}'", remaining_token.start)

        return node

    # Grammar rules based on precedence (Low to High)

    def parse_expression(self) -> ASTNode:
        # Handles addition and subtraction (Left Associative)
        node = self.parse_term()

        while True:
            token = self.peek()
            if token and token.type == 'OP' and token.value in ('+', '-'):
                op = token.value
                self.consume('OP', op)
                right = self.parse_term()
                # Create binary operation node, using the operator's position for error reporting
                node = BinaryOpNode(op, node, right, token.start)
            else:
                break
        return node

    def parse_term(self) -> ASTNode:
        # Handles multiplication and division (Left Associative)
        node = self.parse_factor()

        while True:
            token = self.peek()
            if token and token.type == 'OP' and token.value in ('*', '/'):
                op = token.value
                self.consume('OP', op)
                right = self.parse_factor()
                # Create binary operation node
                node = BinaryOpNode(op, node, right, token.start)
            else:
                break
        return node

    def parse_factor(self) -> ASTNode:
        # Handles numbers, unary minus, and parentheses
        token = self.peek()
        if not token:
            raise CalcError("Unexpected end of expression: Expected operand", len(self.tokens[0].value) if self.tokens else 0)

        # Handle Unary Minus first
        if token.type == 'UNARY_MINUS':
            op_token = self.consume('UNARY_MINUS')
            # Recursively parse the factor that follows the unary minus
            child = self.parse_factor()
            return UnaryOpNode('-', child, op_token.start)

        # Handle Parentheses
        elif token.type == 'LPAREN':
            self.consume('LPAREN')
            # Parse the subexpression inside the parentheses
            node = self.parse_expression()
            # Check for closing parenthesis
            self.consume('RPAREN')
            return node

        # Handle Numbers
        elif token.type == 'NUMBER':
            token = self.consume('NUMBER')
            return NumberNode(token.value, token.start)

        # Syntax Error: If we reached here, the token was not a valid start of a factor
        else:
            # Report error at the position of the invalid token
            raise CalcError(f"Syntax error: Unexpected token {token.type} ('{token.value}')", token.start)

# --- Main Entry Point ---
def evaluate(expr: str) -> Fraction:
    """Evaluates an arithmetic expression exactly and reports errors with their position."""
    if not expr.strip():
        return Fraction(0) # Per requirement for '' -> 0

    # 1. Tokenize
    tokenizer = Tokenizer(expr)
    tokens = tokenizer.tokenize()

    # 2. Parse and Build AST
    parser = Parser(tokens)
    ast_root = parser.parse()

    # 3. Evaluate AST
    return ast_root.evaluate()


# --- Testing (To verify implementation) ---
if __name__ == '__main__':
    def test_eval(expr):
        print(f"\n>>> Evaluating: '{expr}'")
        try:
            result = evaluate(expr)
            print(f"SUCCESS. Result: {result} (Fraction: {result.numerator}/{result.denominator})")
        except CalcError as e:
            print(f"ERROR CAUGHT: {e}")
        except Exception as e:
            print(f"UNEXPECTED ERROR: {e}")

    # Positive Tests
    test_eval('0.1 + 0.2') # 3/10
    test_eval('8 - 3 - 2') # 3
    test_eval('8 / 4 / 2') # 1
    test_eval('2 * -3') # -6
    test_eval('2 - -3') # 5
    test_eval('--4') # -4
