class ExpressionNode:
    """Base class for nodes in the expression tree."""
    pass

class NumberNode(ExpressionNode):
    def __init__(self, value: Fraction, start: int, end: int):
        self.value = value
        self.start = start
        self.end = end

    def evaluate(self) -> Fraction:
        return self.value

class VariableNode(ExpressionNode):
    def __init__(self, name: str, start: int, end: int):
        self.name = name
        self.start = start
        self.end = end

    def evaluate(self, variables: Optional[Dict[str, Union[int, Fraction]]]) -> Fraction:
        if variables is None:
            raise CalcError(f"Unknown variable '{self.name}'", self.start) # Rule: Unknown var when variables=None
        if self.name not in variables:
            raise CalcError(f"Unknown variable '{self.name}'", self.start) # Rule: Unknown var

        val = variables[self.name]
        if isinstance(val, int): 
            return Fraction(val)
        if isinstance(val, Fraction): 
            return val
        raise TypeError(f"Variable '{self.name}' has invalid type in variables map.")

class FunctionCallNode(ExpressionNode):
    def __init__(self, name: str, args: List[ExpressionNode], start: int, end: int):
        self.name = name
        self.args = args
        self.start = start # Position of the function name
        self.end = end # Position after the last argument

    def evaluate(self, variables: Optional[Dict[str, Union[int, Fraction]]]) -> Fraction:
        # 1. Evaluate all arguments first
        evaluated_args = [arg.evaluate(variables) for arg in self.args]

        # 2. Check function validity
        if self.name == 'abs':
            if len(evaluated_args) != 1:
                raise CalcError(f"Function 'abs' requires exactly 1 argument, got {len(evaluated_args)}", self.start)
            return abs(evaluated_args[0])

        elif self.name in ['min', 'max']:
            if len(evaluated_args) < 1:
                raise CalcError(f"Function '{self.name}' requires at least 1 argument, got 0", self.start)

            if self.name == 'min':
                return min(evaluated_args)
            else: # max
                return max(evaluated_args)

        # Should not happen if parsing is correct
        raise CalcError(f"Unknown function '{self.name}'", self.start)

class BinaryOpNode(ExpressionNode):
    def __init__(self, left: ExpressionNode, op: str, right: ExpressionNode, op_start: int):
        self.left = left
        self.op = op
        self.right = right
        self.op_start = op_start

    def evaluate(self, variables: Optional[Dict[str, Union[int, Fraction]]]) -> Fraction:
        left_val = self.left.evaluate(variables)
        right_val = self.right.evaluate(variables)

        if self.op == '/' and right_val == 0:
            # Division by zero: position is the start of the '/' operator
            raise CalcError("Division by zero", self.op_start)

        if self.op == '+':
            return left_val + right_val
        elif self.op == '-':
            return left_val - right_val
        elif self.op == '*':
            return left_val * right_val
        elif self.op == '/':
            return left_val / right_val
        raise RuntimeError(f"Unknown binary operator: {self.op}")

class UnaryOpNode(ExpressionNode):
    def __init__(self, operand: ExpressionNode, op_start: int):
        self.operand = operand
        self.op_start = op_start

    def evaluate(self, variables: Optional[Dict[str, Union[int, Fraction]]]) -> Fraction:
        operand_val = self.operand.evaluate(variables)
        if self.op == 'OP_UNARY_MINUS':
            return -operand_val
        raise RuntimeError(f"Unknown unary operator: {self.op}")


