        # Start parsing from the lowest precedence level (terms) which handles addition/subtraction
        node = self._parse_terms()

        # Check for trailing tokens
        if self.current_token() is not None:
            token = self.current_token()
            raise CalcError(f"Syntax error: Unexpected token '{token.value}' at end of expression", token.start)

        return node

