        self.name = name
        self.start = start
        self.end = end

    def evaluate(self, variables: Optional[Dict[str, Any]]) -> Fraction:
        if variables is None:
            raise CalcError(f"Unknown variable: {self.name}", self.start)

        if self.name not in variables:
            raise CalcError(f"Unknown variable: {self.name}", self.start)

        value = variables[self.name]
        if isinstance(value, int): 
            return Fraction(value)
        elif isinstance(value, Fraction):
