    def __init__(self, func_name: str, args: list[ExpressionNode], func_start: int):
        self.func_name = func_name
        self.args = args
        self.func_start = func_start

    def evaluate(self, variables: Optional[Dict[str, Any]]) -> Fraction:
        args_values = [arg.evaluate(variables) for arg in self.args]

        if self.func_name == "abs":
            if len(args_values) != 1:
                raise CalcError(f"abs() requires exactly one argument, got {len(args_values)}", self.func_start)
            return abs(args_values[0])

        elif self.func_name in ("min", "max"):
            if not args_values: # e.g. min()
                raise CalcError(f"{self.func_name}() requires at least one argument", self.func_start)
            # For min/max, we convert Fraction objects to a comparable type if necessary, but direct comparison usually works for Fraction
            if self.func_name == "min":
                return min(args_values)
            else: # max
                return max(args_values)

        else:
            raise CalcError(f"Unknown function: {self.func_name}", self.func_start)

class BinaryOpNode(ExpressionNode):
    def __init__(self, left: ExpressionNode, op: str, right: ExpressionNode, op_start: int):
        self.left = left
        self.op = op
        self.right = right
        self.op_start = op_start

    def evaluate(self, variables: Optional[Dict[str, Any]]) -> Fraction:
        left_val = self.left.evaluate(variables)
        right_val = self.right.evaluate(variables)

        if self.op == '/':
            if right_val == 0:
                raise CalcError("Division by zero", self.op_start)
            return left_val / right_val
        elif self.op == '+':
            return left_val + right_val
        elif self.op == '-':
            return left_val - right_val
        elif self.op == '*':
            return left_val * right_val
        elif self.op == '**':
            # --- Exponentiation Logic ---
            # 1. Check if exponent is a whole number
            if right_val.denominator != 1:
                raise CalcError("Exponent must be a whole number", self.op_start)

            exponent_int = right_val.numerator

            # 2. Check for 0 raised to a negative power
            if left_val == 0 and exponent_int < 0:
                raise CalcError("0 raised to a negative power is undefined", self.op_start)

            # 3. Calculate power
            # Note: Fraction.power() handles this correctly for integer exponents
            return left_val ** exponent_int

        raise CalcError("Unknown binary operator", self.op_start)

class UnaryOpNode(ExpressionNode):
    def __init__(self, operand: ExpressionNode, op_start: int):
        self.operand = operand
        self.op_start = op_start

    def evaluate(self, variables: Optional[Dict[str, Any]]) -> Fraction:
        operand_val = self.operand.evaluate(variables)
        if self.op == 'OP_UNARY_MINUS':
            return -operand_val
        raise CalcError("Unknown unary operator", self.op_start)

class PowerNode(ExpressionNode):
    # This node is only needed to enforce right-associativity in parsing
    def __init__(self, left: ExpressionNode, right: ExpressionNode, op_start: int):
        self.left = left
        self.right = right
        self.op_start = op_start

    def evaluate(self, variables: Optional[Dict[str, Any]]) -> Fraction:
        # Delegate evaluation to BinaryOpNode which contains the logic
        return BinaryOpNode(self.left, '**', self.right, self.op_start).evaluate(variables)


# --- Parser Implementation (Recursive Descent/Operator Precedence) ---

class Parser:
    """Handles parsing tokens into an Abstract Syntax Tree (AST)."""
    def __init__(self, tokens: list[Token]):
        self.tokens = tokens
        self.pos = 0

    def current_token(self) -> Token | None:
        return self.tokens[self.pos] if self.pos < len(self.tokens) else None

    def consume(self, expected_type: Optional[str] = None, expected_value: Optional[str] = None) -> Token:
        token = self.current_token()
        if not token:
            # Use a large arbitrary position for EOF errors if the actual position cannot be known
            raise CalcError("Unexpected end of expression", 0)

        if expected_type and token.type != expected_type:
            raise CalcError(f"Syntax error: Expected {expected_type}, got {token.type} ('{token.value}')", token.start)
        if expected_value and token.value != expected_value:
            raise CalcError(f"Syntax error: Expected '{expected_value}', got '{token.value}'", token.start)

        self.pos += 1
        return token

    def parse(self) -> ExpressionNode:
        # Start parsing from the lowest precedence level (terms) which handles addition/subtraction
        node = self._parse_terms()

        # Check for trailing tokens (e.g., '1 2' or '1 +')
        if self.current_token() is not None:
            token = self.current_token()
            if token.type != 'RPAREN': 
                 raise CalcError("Syntax error: Unexpected token at end of expression", token.start)

        return node

    def _parse_terms(self) -> ExpressionNode: # Handles + and -
        node = self._parse_power()

        while self.current_token() and self.current_token().type in ['OP_PLUS', 'OP_MINUS']:
            op_token = self.consume()
            right = self._parse_power()
            node = BinaryOpNode(node, op_token.value, right, op_token.start)
        return node

    def _parse_power(self) -> ExpressionNode: # Handles ** (Right-associative, highest binary precedence)
        left = self._parse_unary()

        token = self.current_token()
        if token and token.type == 'OP_POWER':
            op_token = self.consume()
            # Right-associative: recursively call _parse_power for the right side
            right = self._parse_power()
            return PowerNode(left, right, op_token.start)
        return left

    def _parse_factor(self) -> ExpressionNode: # Handles * and / (Multiplication/Division)
        node = self._parse_unary()

        while self.current_token() and self.current_token().type in ['OP_MUL', 'OP_DIV']:
            op_token = self.consume()
            right = self._parse_unary()
            node = BinaryOpNode(node, op_token.value, right, op_token.start)
        return node

    def _parse_unary(self) -> ExpressionNode: # Handles unary minus
        token = self.current_token()
        if token and token.type == 'OP_UNARY_MINUS':
            op_token = self.consume()
            # Allow chained unary minus
            operand = self._parse_unary() 
            return UnaryOpNode(operand, op_token.start)

        # If not unary minus, parse primary (number/parentheses/identifier/function call)
        return self._parse_primary()

    def _parse_primary(self) -> ExpressionNode:
        token = self.current_token()

        if not token:
            raise CalcError("Syntax error: Empty expression", 0)

        if token.type == 'NUMBER':
            self.consume('NUMBER')
            value = Fraction(token.value)
            return NumberNode(value, token.start, token.end)

        elif token.type == 'IDENTIFIER':
            name_token = self.consume('IDENTIFIER')
            next_token = self.current_token()

            if next_token and next_token.type == 'LPAREN':
                # It's a function call
                self.consume('LPAREN')
                args = []

                # Parse arguments until ')' or end of expression (handled by parser cleanup)
                while self.current_token() and self.current_token().type != 'RPAREN':
                    # Parse argument expression recursively, starting at the lowest level (terms)
                    arg_node = self._parse_terms() 
                    args.append(arg_node)

                    # Check for comma separator
                    if self.current_token() and self.current_token().type == ',':
                        self.consume(',')
                    elif self.current_token() and self.current_token().type != 'RPAREN':
                         # Catches missing comma between arguments or trailing garbage
                         raise CalcError("Syntax error: Expected ',' or ')', found unexpected token", self.current_token().start)

                self.consume('RPAREN')
                return FunctionCallNode(name_token.value, args, name_token.start)
            else:
                # It's a variable
                return VariableNode(name_token.value, name_token.start, name_token.end)

        elif token.type == 'LPAREN':
            self.consume('LPAREN')
            node = self._parse_terms() 
            self.consume('RPAREN') 
            return node

        else:
            raise CalcError("Syntax error: Unexpected token", token.start)


# --- Main Evaluation Function ---

def evaluate(expr: str, variables: Optional[Dict[str, Any]] = None) -> Fraction:
    """Evaluates an arithmetic expression string exactly, supporting variables and functions.

    :param expr: The expression string.
    :param variables: Mapping from variable names to int or Fraction values.
    :raises CalcError: For syntax or runtime arithmetic errors.
    :return: The result as a Fraction.
    """
    if not expr.strip():
        raise CalcError("Input expression cannot be empty", 0)

    # 1. Tokenize
    tokens = tokenize(expr)

    # 2. Parse
    parser = Parser(tokens)
    try:
        ast_root = parser.parse()
    except CalcError as e:
        # Re-raise parsing errors immediately
        raise e

    # 3. Evaluate
    return ast_root.evaluate(variables)


