def _pad_cell(text: str, width: int, alignment: str) -> str:
    """Pads a cell string to the required width based on alignment."""
    if len(text) >= width:
        return text

    padding_needed = width - len(text)

    if alignment == 'left':
        # Right-pad (left-aligned)
        return text + ' ' * padding_needed
    elif alignment == 'right':
        # Left-pad (right-aligned)
        return ' ' * padding_needed + text
    elif alignment == 'center':
        # Center-align: split padding, smaller half on the left
        left_padding = padding_needed // 2
        right_padding = padding_needed - left_padding
        return ' ' * left_padding + text + ' ' * right_padding
    else:
        # This case should be caught earlier by validation, but for safety:
        raise ValueError(f"Unknown alignment specified: {alignment}")

def format_row_line(cells: list[str], widths: list[int], alignments: list[str]) -> str:
    """Formats a single row of cells into a Markdown line."""
    if len(cells) != len(widths) or len(cells) != len(alignments):
        raise ValueError("Mismatch between cells, widths, and alignments provided for the row.")

    padded_cells = []
    for cell, width, alignment in zip(cells, widths, alignments):
        padded_cells.append(_pad_cell(cell, width, alignment))

    # The output format is: '| ' + padded_cells_joined_by_separator + ' |'
    return '| ' + ' | '.join(padded_cells) + ' |'

