def parse(text: str) -> list[list[int]]:
    """Reads 81 cells from a string in row-major order.

    Digits '1'–'9' are givens; '0' and '.' are empty cells; whitespace is ignored.

    Raises ValueError if the cell count is not 81 or if invalid characters are present.
    """
    # 1. Normalize and filter out whitespace
    chars = [c for c in text if not c.isspace()]

    # 2. Check total cell count
    if len(chars) != 81:
        raise ValueError(f"Expected 81 cells, but found {len(chars)}.")

    grid = []
    cell_index = 0

    # 3. Process each character
    for char in chars:
        if char.isdigit():
            digit = int(char)
            # Check for invalid digits (must be 0-9, although filtering above ensures this, 
            # we check against constraints for robustness if the input was not purely digits/dots)
            if 1 <= digit <= 9:
                value = digit
            elif digit == 0:
                value = 0
            else:
                # Should not happen if char.isdigit() is true and we handle 0 correctly, but for strictness:
                raise ValueError(f"Invalid digit '{char}' encountered in input text.")
        elif char == '.':
            value = 0  # '.' represents an empty cell
        else:
            # Invalid character check
            raise ValueError(f"Invalid character '{char}' found in input text. Only digits 0-9 and '.' are allowed.")

        # Build the grid row by row
        if len(grid) < 9:
            if len(grid) == 0: # Start of a new row
                grid.append([])
            grid[-1].append(value)

            # Check for row completion
            if len(grid[-1]) == 9:
                # Move to next row
                grid.append([])
        else:
            # This case should ideally not be reached if total count is 81, but serves as a final safeguard
            raise RuntimeError("Internal error: Grid structure exceeded 9 rows before 81 cells were processed.")

    # Final check to ensure exactly 9 rows were created
    if len(grid) != 9:
        raise ValueError("Failed to form a complete 9x9 grid structure.")

    return grid

