def validate_grid_structure(grid: List[List[int]]):
    """Checks if the grid is a 9x9 list of lists containing integers 0-9.

    Raises ValueError if the grid does not meet the required structure.
    """
    if not isinstance(grid, list) or len(grid) != 9:
        raise ValueError("Grid must have 9 rows.")

    for i, row in enumerate(grid):
        if not isinstance(row, list) or len(row) != 9:
            raise ValueError(f"Row {i} must have 9 columns.")
        for j, cell in enumerate(row):
            if not isinstance(cell, int) or not (0 <= cell <= 9):
                raise ValueError(f"Cell at ({i}, {j}) must be an integer between 0 and 9. Found: {cell}")

