def to_string(grid: List[List[int]]) -> str:
    """Converts a 9x9 grid into an 81-character string representation.

    Empty cells (0) are represented by '.', and no whitespace is used.

    Raises ValueError if the grid does not have the required 9x9 shape or contains invalid values.
    """
    validate_grid_structure(grid)

    result_chars = []
    for row in grid:
        for cell in row:
            if cell == 0:
                result_chars.append('.')
            else:
                result_chars.append(str(cell))

    return "".join(result_chars)

# --- Candidate Generation ---

def get_candidates(grid: List[List[int]], row: int, col: int) -> set[int]:
    """Calculates the set of valid candidates (1-9) for the cell at (row, col).

    Raises ValueError if the grid structure is invalid.
    """
    validate_grid_structure(grid)

    if grid[row][col] != 0:
        return set()

    used_in_row = set(grid[row]) - {0}
    used_in_col = set(grid[r][col] for r in range(9)) - {0}

    # Determine box
    box_row_start = (row // 3) * 3
    box_col_start = (col // 3) * 3
    used_in_box = set()

    for i in range(box_row_start, box_row_start + 3):
        for j in range(box_col_start, box_col_start + 3):
            used_in_box.add(grid[i][j])

    all_used = used_in_row.union(used_in_col).union(used_in_box)
    candidates = {i for i in range(1, 10) if i not in all_used}

    return candidates

