import copy
from typing import List, Tuple, Dict, Optional

# --- Validation Utilities ---

def validate_grid_structure(grid: List[List[int]]):
    """Checks if the grid is a 9x9 list of lists containing integers 0-9.

    Raises ValueError if the grid does not meet the required structure.
    """
    if not isinstance(grid, list) or len(grid) != 9:
        raise ValueError("Grid must have 9 rows.")

    for i, row in enumerate(grid):
        if not isinstance(row, list) or len(row) != 9:
            raise ValueError(f"Row {i} must have 9 columns.")
        for j, cell in enumerate(row):
            if not isinstance(cell, int) or not (0 <= cell <= 9):
                raise ValueError(f"Cell at ({i}, {j}) must be an integer between 0 and 9. Found: {cell}")

# --- Grid Representation and Conversion ---

def to_string(grid: List[List[int]]) -> str:
    """Converts a 9x9 grid into an 81-character string representation.

    Empty cells (0) are represented by '.', and no whitespace is used.

    Raises ValueError if the grid does not have the required 9x9 shape or contains invalid values.
    """
    validate_grid_structure(grid)

    result_chars = []
    for row in grid:
        for cell in row:
            if cell == 0:
                result_chars.append('.')
            else:
                result_chars.append(str(cell))

    return "".join(result_chars)

# --- Candidate Generation ---

def get_candidates(grid: List[List[int]], row: int, col: int) -> set[int]:
    """Calculates the set of valid candidates (1-9) for the cell at (row, col).

    Raises ValueError if the grid structure is invalid.
    """
    validate_grid_structure(grid)

    if grid[row][col] != 0:
        return set()

    used_in_row = set(grid[row]) - {0}
    used_in_col = set(grid[r][col] for r in range(9)) - {0}

    # Determine box
    box_row_start = (row // 3) * 3
    box_col_start = (col // 3) * 3
    used_in_box = set()

    for i in range(box_row_start, box_row_start + 3):
        for j in range(box_col_start, box_col_start + 3):
            used_in_box.add(grid[i][j])

    all_used = used_in_row.union(used_in_col).union(used_in_box)
    candidates = {i for i in range(1, 10) if i not in all_used}

    return candidates

# --- Validity Checks ---

def is_valid(grid: List[List[int]]) -> bool:
    """Checks if the grid is valid by verifying no digit 1-9 appears twice in any row, column or 3x3 box.

    Raises ValueError if the grid does not have the correct 9x9 structure and values.
    """
    # 1. Structure and value validation
    validate_grid_structure(grid)

    # Helper function to check for duplicates in a list of numbers (ignoring 0)
    def has_duplicates(data: List[int]) -> bool:
        seen = set()
        for item in data:
            if item != 0:
                if item in seen:
                    return True
                seen.add(item)
        return False

    # 2. Check Rows
    for row in grid:
        if has_duplicates(row):
            return False

    # 3. Check Columns
    for col_index in range(9):
        column = [grid[row_index][col_index] for row_index in range(9)]
        if has_duplicates(column):
            return False

    # 4. Check 3x3 Boxes
    for box_row_start in range(0, 9, 3):
        for box_col_start in range(0, 9, 3):
            box = []
            for i in range(3):
                for j in range(3):
                    r = box_row_start + i
                    c = box_col_start + j
                    box.append(grid[r][c])
            if has_duplicates(box):
                return False

    return True

# --- Solver Functions ---

def solve(grid: List[List[int]]) -> Optional[List[List[int]]]:
    """
    Solves the Sudoku puzzle using backtracking.
    Returns a completed, valid grid, or None if no solution exists.
    The original grid is never modified.
    """
    if not is_valid(grid):
        return None

    # Find the next empty cell (0)
    empty_cell = None
    for r in range(9):
        for c in range(9):
            if grid[r][c] == 0:
                empty_cell = (r, c)
                break
        if empty_cell:
            break

    # Base case: If no empty cells are found, the grid is solved.
    if not empty_cell:
        return copy.deepcopy(grid)

    row, col = empty_cell

    # Try digits 1 through 9
    for num in range(1, 10):
        # Place the number tentatively on a copy of the grid state for recursion safety
        temp_grid = copy.deepcopy(grid)
        temp_grid[row][col] = num

        if is_valid(temp_grid):
            # Recurse
            result = solve(temp_grid)

            if result is not None:
                return result

    # Exhausted all possibilities for this cell, return None
    return None

def count_solutions(grid: List[List[int]], limit: int = 2) -> int:
    """
    Counts the number of valid solutions for a Sudoku grid, stopping at 'limit'.
    Raises ValueError if limit < 1.
    The input grid is never modified.
    """
    if limit < 1:
        raise ValueError("Limit must be 1 or greater.")

    if not is_valid(grid):
        return 0

    # Use a helper function for recursive counting
    def _backtrack_count(current_grid: List[List[int]], count_limit: int) -> int:
        if count_limit <= 0:
            return 0

        # Find the next empty cell
        empty_cell = None
        for r in range(9):
            for c in range(9):
                if current_grid[r][c] == 0:
                    empty_cell = (r, c)
                    break
            if empty_cell:
                break

        # Base case: Grid is full and valid
        if not empty_cell:
            return 1

        row, col = empty_cell
        total_solutions = 0

        # Try digits 1 through 9
        for num in range(1, 10):
            # Place the number tentatively on a *copy* of the current grid state
            next_grid = [row[:] for row in current_grid]
            next_grid[row][col] = num

            if is_valid(next_grid):
                # Recurse and accumulate count
                solutions_from_here = _backtrack_count(next_grid, count_limit - total_solutions)
                total_solutions += solutions_from_here

                # Check if the global limit has been reached
                if total_solutions >= count_limit:
                    return total_solutions

        return total_solutions

    return _backtrack_count(copy.deepcopy(grid), limit)

# --- Hint Logic Implementation ---

def hint(grid: List[List[int]]) -> Optional[Tuple[int, int, int, str]]:
    """Returns the next logical step as (row, col, digit, reason), or None if no step exists.
    """
    validate_grid_structure(grid)

    # Check for completion
    if all(cell != 0 for row in grid for cell in row):
        if is_valid(grid):
             return None
        else:
             raise ValueError("Grid is complete but invalid.")

    # Check for general invalidity if partially filled
    if not is_valid(grid):
        raise ValueError("Grid is not a valid starting state.")

    # 1. Naked Single Search (Row-major order)
    for r in range(9):
        for c in range(9):
            if grid[r][c] == 0:
                candidates = get_candidates(grid, r, c)
                if len(candidates) == 1:
                    digit = candidates.pop()
                    return (r, c, digit, 'naked single')

    # 2. Hidden Single Search

    # 2a. Hidden Single in Rows
    for r in range(9):
        for d in range(1, 10):
            # Collect all empty cells in this row
            row_cells = [(r, c) for c in range(9) if grid[r][c] == 0]

            # Check if 'd' is a candidate for exactly one cell in this row
            candidates_for_d = []
            for r_cell, c_cell in row_cells:
                if d in get_candidates(grid, r_cell, c_cell):
                    candidates_for_d.append((r_cell, c_cell))

            if len(candidates_for_d) == 1:
                r_found, c_found = candidates_for_d[0]
                return (r_found, c_found, d, 'hidden single in row')

    # 2b. Hidden Single in Columns
    for c in range(9):
        for d in range(1, 10):
            # Collect all empty cells in this column
            col_cells = [(r, c) for r in range(9) if grid[r][c] == 0]

            # Check if 'd' is a candidate for exactly one cell in this column
            candidates_for_d = []
            for r_cell, c_cell in col_cells:
                if d in get_candidates(grid, r_cell, c_cell):
                    candidates_for_d.append((r_cell, c_cell))

            if len(candidates_for_d) == 1:
                r_found, c_found = candidates_for_d[0]
                return (r_found, c_found, d, 'hidden single in column')

    # 2c. Hidden Single in Boxes
    for b in range(9):
        box_row_start = (b // 3) * 3
        box_col_start = (b % 3) * 3

        # Collect all empty cells in this box
        box_cells = []
        for r_offset in range(3):
            for c_offset in range(3):
                r = box_row_start + r_offset
                c = box_col_start + c_offset
                if grid[r][c] == 0:
                    box_cells.append((r, c))

        for d in range(1, 10):
            # Check if 'd' is a candidate for exactly one cell in this box
            candidates_for_d = []
            for r_cell, c_cell in box_cells:
                if d in get_candidates(grid, r_cell, c_cell):
                    candidates_for_d.append((r_cell, c_cell))

            if len(candidates_for_d) == 1:
                r_found, c_found = candidates_for_d[0]
                return (r_found, c_found, d, 'hidden single in box')

    # 3. No step found
    return None

# --- Difficulty Calculation ---

def difficulty(grid: List[List[int]]) -> Optional[Dict[str, int]]:
    """Measures the puzzle's difficulty by counting the steps (naked vs hidden) required to complete the puzzle using hint().

    Operates on a copy of the grid. Returns {'naked': N, 'hidden': H} if completeable by hints,
    or None if hints run out before completion. Raises ValueError if the initial grid is invalid.
    """
    # 1. Initial validation
    try:
        if not is_valid(grid):
            raise ValueError("Grid is not a valid starting state.")
    except ValueError as e:
        # Re-raise structural/validity errors from is_valid
        raise e

    # 2. Setup
    working_grid = copy.deepcopy(grid)
    step_counts = {'naked': 0, 'hidden': 0}

    while True:
        hint_result = hint(working_grid)

        # Check for completion
        is_complete = all(cell != 0 for row in working_grid for cell in row)
        if is_complete:
            # The hint function ensures the grid is valid if complete
            return step_counts

        # Check if no further progress can be made
        if hint_result is None:
            # If not complete and hint returns None, the puzzle is not solvable by the hint mechanism
            return None

        # 3. Apply hint and count step
        row, col, digit, reason = hint_result
        working_grid[row][col] = digit

        if reason == 'naked single':
            step_counts['naked'] += 1
        elif 'hidden single' in reason:
            step_counts['hidden'] += 1

