        select_token = self.consume('KEYWORD', 'SELECT')
        select_list = self._parse_select_list()

        # 2. FROM clause
        from_token = self.consume('KEYWORD', 'FROM')
        table_name = self.consume('IDENT').value

        # 3. WHERE clause (Optional)
        where_condition = None
        if self.peek().kind == 'KEYWORD' and self.peek().value == 'WHERE':
            self.consume('KEYWORD', 'WHERE')
            where_condition = self._parse_condition()

        # 4. ORDER BY clause (Optional)
        order_by_list = []
        if self.peek().kind == 'KEYWORD' and self.peek().value == 'ORDER':
            self.consume('KEYWORD', 'ORDER')
            self.consume('KEYWORD', 'BY')
            order_by_list = self._parse_order_by()

        # 5. LIMIT clause (Optional)
        limit_val = None
        if self.peek().kind == 'KEYWORD' and self.peek().value == 'LIMIT':
            self.consume('KEYWORD', 'LIMIT')
            limit_token = self.consume('NUMBER')
            limit_val = int(limit_token.value)

