        right_val = evaluate_condition(condition_node.right, row, tables)

        if left_val == FALSE_VAL or right_val == FALSE_VAL:
            return FALSE_VAL # AND is false if either side is false
        if left_val == FALSE_VAL or right_val == FALSE_VAL: # This case is redundant but keeps logic clear
             return FALSE_VAL
        if left_val == TRUE_VAL and right_val == TRUE_VAL:
            return TRUE_VAL # If both are true
        return UNKNOWN # Otherwise (one is unknown)

    elif isinstance(condition_node, Or):
        # Rule 5: OR logic
        left_val = evaluate_condition(condition_node.left, row, tables)
        right_val = evaluate_condition(condition_node.right, row, tables)

        if left_val == TRUE_VAL or right_val == TRUE_VAL:
            return TRUE_VAL # OR is true if either side is true
        if left_val == TRUE_VAL or right_val == TRUE_VAL:
             return TRUE_VAL
        return UNKNOWN # Otherwise (one is unknown)

    elif isinstance(condition_node, Not):
        # Rule 5: NOT logic
        operand_val = evaluate_condition(condition_node.operand, row, tables)
        if operand_val == TRUE_VAL: return FALSE_VAL
        if operand_val == FALSE_VAL: return TRUE_VAL
        return UNKNOWN # NOT of unknown is unknown

    elif isinstance(condition_node, Compare):
        # Assumes Compare holds (op, left_node, right_node)
        op_str = condition_node.op
        # Simplified: Assume left/right nodes resolve directly to values for this placeholder
