import re
from dataclasses import dataclass
from typing import Any, List, Tuple, Optional

# Assume these are available from minisql.tokens
# from minisql.tokens import Token, SQLSyntaxError

# --- Mock imports for completeness, assuming they exist in reality ---
class Token: 
    def __init__(self, kind: str, value: Any, pos: int): 
        self.kind = kind 
        self.value = value 
        self.pos = pos

class SQLSyntaxError(Exception): 
    def __init__(self, message: str, pos: int): 
        super().__init__(message)
        self.pos = pos

# --- AST Definitions ---

@dataclass(frozen=True)
class Column:
    name: str

@dataclass(frozen=True)
class Literal:
    value: Any  # int, float, str, bool, None

@dataclass(frozen=True)
class Compare:
    op: str
    left: Any  # AST node or Literal
    right: Any # AST node or Literal

@dataclass(frozen=True)
class And:
    left: Any
    right: Any

@dataclass(frozen=True)
class Or:
    left: Any
    right: Any

@dataclass(frozen=True)
class Not:
    operand: Any

@dataclass(frozen=True)
class IsNull:
    operand: Any
    negated: bool

@dataclass(frozen=True)
class Select:
    columns: Optional[List[str]]  # None for *, else list of names
    table: str
    where: Optional[Any]  # Condition AST node or None
    order_by: List[Tuple[str, bool]] # (name, descending)
    limit: Optional[int]

# --- Parser Implementation ---

class Parser:
    def __init__(self, tokens: List[Token]):
        self.tokens = tokens
        self.pos = 0

    def peek(self) -> Token: 
        if self.pos < len(self.tokens): 
            return self.tokens[self.pos]
        # Should not happen if EOF token is correctly placed
        return Token('EOF', None, len(self.tokens[-1].value) if self.tokens else 0)

    def consume(self, expected_kind: str = None, expected_value: Optional[str] = None) -> Token:
        token = self.peek()
        if expected_kind and token.kind != expected_kind: 
            raise SQLSyntaxError(f"Expected token of kind {expected_kind}, got {token.kind} ({token.value})", token.pos)
        if expected_value and token.value != expected_value: 
            raise SQLSyntaxError(f"Expected token value '{expected_value}', got '{token.value}'", token.pos)
        self.pos += 1
        return token

    def parse(self) -> Select:
        # 1. SELECT clause
        select_token = self.consume('KEYWORD', 'SELECT')
        select_list = self._parse_select_list()

        # 2. FROM clause
        from_token = self.consume('KEYWORD', 'FROM')
        table_name = self.consume('IDENT').value

        # 3. WHERE clause (Optional)
        where_condition = None
        if self.peek().kind == 'KEYWORD' and self.peek().value == 'WHERE':
            self.consume('KEYWORD', 'WHERE')
            where_condition = self._parse_condition()

        # 4. ORDER BY clause (Optional)
        order_by_list = []
        if self.peek().kind == 'KEYWORD' and self.peek().value == 'ORDER':
            self.consume('KEYWORD', 'ORDER')
            self.consume('KEYWORD', 'BY')
            order_by_list = self._parse_order_by()

        # 5. LIMIT clause (Optional)
        limit_val = None
        if self.peek().kind == 'KEYWORD' and self.peek().value == 'LIMIT':
            self.consume('KEYWORD', 'LIMIT')
            limit_token = self.consume('NUMBER')
            limit_val = int(limit_token.value)

        # Final check for EOF
        if self.peek().kind != 'EOF':
            raise SQLSyntaxError(f"Unexpected token after statement completion: {self.peek().value}", self.peek().pos)

        return Select(
            columns=select_list if select_list != '*' else None,
            table=table_name,
            where=where_condition,
            order_by=order_by_list,
            limit=limit_val
        )

    def _parse_select_list(self) -> Optional[List[str]]:
        # Check for '*' first
        if self.peek().kind == 'STAR':
            self.consume('STAR')
            return '*' # Representing '*' as the string '*' for simplicity in AST, handled later

        columns = []
        while True:
            col_token = self.consume('IDENT')
            columns.append(col_token.value)

            # Check for next comma or end of clause
            if self.peek().kind == 'COMMA':
                self.consume('COMMA')
            else:
                break

        # Check for duplicate names (Rule: The same name listed twice in the select list is a syntax error.)
        if len(columns) != len(set(columns)): # Checks if all elements are unique
            raise SQLSyntaxError("Duplicate column name found in SELECT list.", columns[columns.index(next(iter(set(columns)) - set(columns)))].pos)

        return columns

    def _parse_order_by(self) -> List[Tuple[str, bool]]:
        items = []
        while True:
            name_token = self.consume('IDENT')
            name = name_token.value

            # Check for direction (ASC/DESC)
            direction = False # Default ASC
            if self.peek().kind == 'KEYWORD' and self.peek().value in ('ASC', 'DESC'):
                dir_token = self.consume('KEYWORD')
                direction = (dir_token.value == 'DESC')

            items.append((name, direction))

            # Check for next item
            if self.peek().kind == 'COMMA':
                self.consume('COMMA')
            else:
                break
        return items

    # --- Condition Parsing (Precedence: NOT > AND > OR) ---

    def _parse_condition(self) -> Any:
        # Start with the lowest precedence: OR
        node = self._parse_and()

        while self.peek().kind == 'KEYWORD' and self.peek().value == 'OR':
            op_token = self.consume('KEYWORD', 'OR')
            right_side = self._parse_and()
            node = Or(node, right_side)

        return node

    def _parse_and(self) -> Any:
        # Next precedence: AND
        node = self._parse_not()

        while self.peek().kind == 'KEYWORD' and self.peek().value == 'AND':
            op_token = self.consume('KEYWORD', 'AND')
            right_side = self._parse_not()
            node = And(node, right_side)

        return node

    def _parse_not(self) -> Any:
        # Next precedence: NOT
        if self.peek().kind == 'KEYWORD' and self.peek().value == 'NOT':
            not_token = self.consume('KEYWORD', 'NOT')
            operand = self._parse_comparison() # NOT applies to a whole comparison/operand
            return Not(operand)
