            null_token = self.consume('KEYWORD', 'NULL')
            operand = self._parse_primary_operand() # Operand must precede IS NULL/NOT NULL

            is_not = (self.peek().kind == 'KEYWORD' and self.peek().value == 'NOT')
            if is_not:
                self.consume('KEYWORD', 'NOT')
