        while self.peek().kind == 'KEYWORD' and self.peek().value == 'JOIN':
            self.consume('KEYWORD', 'JOIN')
            joined_table = self.consume('IDENT').value

            # Parse ON clause
            self.consume('KEYWORD', 'ON')
            # Note: We must consume the tokens, but only track the Column object.
            left_col = self._parse_primary_operand() 
            right_col = self._parse_primary_operand() 

            # Validation: Check if left_col and right_col are Columns
            if not isinstance(left_col, Column) or not isinstance(right_col, Column):
