        group_by_list = []
        if self.peek().kind == 'KEYWORD' and self.peek().value == 'GROUP':
            self.consume('KEYWORD', 'GROUP')
            self.consume('KEYWORD', 'BY')
            group_by_list = self._parse_group_by()

        # 6. ORDER BY clause (Optional)
        order_by_list = []
        if self.peek().kind == 'KEYWORD' and self.peek().value == 'ORDER':
            self.consume('KEYWORD', 'ORDER')
            self.consume('KEYWORD', 'BY')
            order_by_list = self._parse_order_by(group_by_list)

        # 7. LIMIT clause (Optional)
        limit_val = None
        if self.peek().kind == 'KEYWORD' and self.peek().value == 'LIMIT':
            self.consume('KEYWORD', 'LIMIT')
            limit_token = self.consume('NUMBER')
            limit_val = int(limit_token.value)

