        if self.peek().kind != 'EOF':
            raise SQLSyntaxError(f"Unexpected token after statement completion: {self.peek().value}", self.peek().pos)

        # --- Syntax Error Checks ---

        is_grouped = bool(group_by_list) or any(isinstance(item[0], Aggregate) for item in select_items if item[0] != '*')

        # Rule: * in grouped query
        if select_items == [('*', '*')] and is_grouped:
             raise SQLSyntaxError("* not allowed in a grouped query.", select_items[0][0].pos if isinstance(select_items[0][0], Column) else self.peek().pos)

        # Rule: Plain ref in grouped query, not in GROUP BY
        for expr, _ in select_items:
            if isinstance(expr, Column) and group_by_list and expr.name not in group_by_list:
                raise SQLSyntaxError(f"Plain reference {expr.name} must be in GROUP BY clause in a grouped query.", expr.pos)

        # Rule: Aggregate in ORDER BY of a non-grouped query
        if not is_grouped and any(isinstance(item[0], Aggregate) for item in select_items if item[0] != '*'):
             raise SQLSyntaxError("Aggregate functions are not allowed in ORDER BY clause of a non-grouped query.", self.tokens[order_by_list[0][0] if order_by_list else 0].pos)

        # Determine output columns list
        if select_items == [('*', '*')]:
            columns_list = None
        else:
            columns_list = [k for _, k in select_items]

        return Select(
            items=select_items,
            columns=columns_list,
            table=table_name,
            join=current_join,
            where=where_condition,
            group_by=group_by_list,
            order_by=order_by_list,
            limit=limit_val
        )

