        alias_name = None
        if self.peek().kind == 'KEYWORD' and self.peek().value == 'AS':
            self.consume('KEYWORD', 'AS')
            alias_token = self.consume('IDENT')
            alias_name = alias_token.value

        # Determine the output key
        if isinstance(expr, Aggregate):
            key = alias_name if alias_name else expr.canonical_text()
        elif isinstance(expr, Column):
            key = alias_name if alias_name else expr.name
        else:
