        if self.peek().kind == 'IDENT' and self.peek().value in ('COUNT', 'SUM', 'AVG', 'MIN', 'MAX'):
            func_token = self.consume('IDENT')
            func = func_token.value.upper()

            self.consume('LPAREN')
            arg = None
            if self.peek().kind == 'STAR':
                self.consume('STAR')
                arg = None
            else:
                arg = self._parse_primary_operand() 

            self.consume('RPAREN')
            return Aggregate(func=func, arg=arg)
        else:
            # Must be a reference (Column)
            return self._parse_column_ref()

    def _parse_column_ref(self) -> Column:
        # ref := name | table . name
        parts = []
        start_pos = self.peek().pos

        while True:
            token = self.peek()
            if token.kind == 'IDENT':
                parts.append(token.value)
                self.consume('IDENT')
            elif token.kind == 'DOT':
                parts.append('.')
                self.consume('DOT')
            else:
