        if left_val == TRUE_VAL or right_val == TRUE_VAL:
             return TRUE_VAL
        return UNKNOWN # Otherwise (one is unknown)

    elif isinstance(condition_node, Not):
        # Rule 5: NOT logic
        operand_val = evaluate_condition(condition_node.operand, row, tables)
        if operand_val == TRUE_VAL: return FALSE_VAL
        if operand_val == FALSE_VAL: return TRUE_VAL
        return UNKNOWN # NOT of unknown is unknown

    elif isinstance(condition_node, Compare):
        # Assumes Compare holds (op, left_node, right_node)
        op_str = condition_node.op
        # Simplified: Assume left/right nodes resolve directly to values for this placeholder
        # In reality, we must recursively evaluate left_node and right_node first.

        # Placeholder: If we had full AST, we'd get val1, val2 here
        try:
            val1 = condition_node.left.resolve_value(row, tables) # Hypothetical method
            val2 = condition_node.right.resolve_value(row, tables) # Hypothetical method
        except AttributeError: 
             # Handle cases where nodes are literals directly
             val1 = condition_node.left.value
             val2 = condition_node.right.value

        return compare_values(val1, val2, op_str)

    elif isinstance(condition_node, IsNull):
        # Rule 5: IS NULL/IS NOT NULL are always true/false
        val = evaluate_condition(condition_node.operand, row, tables)
        if condition_node.negated: # IS NOT NULL
            return TRUE_VAL if val is not None else FALSE_VAL
        else: # IS NULL
            return TRUE_VAL if val is None else FALSE_VAL

    # If the node is a bare operand, it is not a condition (should be caught by parser)
    return UNKNOWN

# --- Sorting Helper ---

def get_sort_key_and_type(row: Dict[str, Any], col_name: str, tables: Dict[str, List[Dict]]) -> Tuple[Value, Optional[type]]:
    """Fetches value and type for sorting. Assumes column exists or returns None.
    """
    # Rule 7: Columns not in select list can be used for ORDER BY.
    # Rule 2: Missing column reads as NULL.
    row_value = row.get(col_name, None)
    col_type = get_type(row_value) # Use helper defined earlier
    return row_value, col_type

def sort_key_comparator(row: Dict[str, Any], col_name: str, descending: bool, tables: Dict[str, List[Dict]]) -> Tuple[int, Any]:
    """
    Returns a tuple used for stable sorting comparison.
    Sorts NULLs before values (ASC) or after values (DESC).
    The first element dictates NULL ordering.
    """
    value, value_type = get_sort_key_and_type(row, col_name, tables)

    if value is None:
        # NULL sorting: ASC -> 0 (comes first); DESC -> 1 (comes last)
        return (0 if not descending else 1, value)
    else:
        # Non-NULL sorting: 1 for all, then the value itself.
        return (1, value)

# --- Main Executor ---

def execute(stmt: Select, tables: Dict[str, List[Dict]]) -> List[Dict]:
    """Runs a parsed statement against the in-memory database."""
    # Rule 1: Table existence check
    if stmt.table not in tables:
        raise SQLExecutionError(f"Unknown table name: {stmt.table}")

    table_data = tables[stmt.table]

    # 1. Filtering (WHERE Clause)
    filtered_rows = []
    if stmt.where is None:
        filtered_rows = table_data
    else:
        for row in table_data:
            # Evaluate condition using three-valued logic
            result = evaluate_condition(stmt.where, row, tables)

            # Rule 6: WHERE keeps rows whose condition is true (not unknown).
            if result == TRUE_VAL:
                filtered_rows.append(row)

    # 2. Sorting (ORDER BY Clause)
    if stmt.order_by:
        # Sort keys are built by combining all ordering criteria
        def combined_sort_key(row: Dict[str, Any]) -> Tuple[Any, ...]:
            keys = []
            for col_name, descending in stmt.order_by:
                # Use the dedicated comparator logic to get a sortable tuple
                # Note: Python's sort handles tuples element by element.
                # We use a stable sort mechanism where the key tuple itself reflects ordering needs.

                # For simplicity and adherence to the stable sort rule (Rule 7):
                # We need to generate a key that respects NULL placement.
                # Since we must sort on multiple columns, we need a complex key.
                # Let's rely on Python's tuple comparison and modify the value slightly.

                value, _ = get_sort_key_and_type(row, col_name, tables)

                if value is None:
                    # NULLs first in ASC (False/0), last in DESC (True/1)
                    null_indicator = False if not descending else True
                    keys.append((null_indicator, value))
                else:
                    # Non-NULLs always come second in the indicator
                    keys.append((True, value))
            return tuple(keys)

        # Python's sort is stable. We sort multiple times for multi-level sorting.
        # Or, we sort using a key tuple that encapsulates all criteria.

        # To handle descending correctly within a tuple key: 
        # For ASC: (NULL_indicator, value)
        # For DESC: (1 - NULL_indicator, -value) -- this is complex for mixed types

        # Simpler approach using functools.cmp_to_key for true custom comparison if types are consistent.
        # Given the stability requirement and mixed types, relying on a carefully constructed key tuple is best.

        # Re-implementing the sort key generation to handle DESC properly:
        def final_sort_key(row: Dict[str, Any]) -> Tuple[Any, ...]:
            sort_items = []
            for col_name, descending in stmt.order_by:
                value, _ = get_sort_key_and_type(row, col_name, tables)

                if value is None:
                    # NULL before in ASC (False), after in DESC (True)
                    sort_items.append((not descending, value)) # (False, None) for ASC, (True, None) for DESC
                else:
                    # Non-NULLs are always treated as 'present' (True)
                    if descending:
                        # For descending, we negate the comparison result if it were numeric
                        # Since types can be mixed, we rely on Python's reverse=True later.
                        sort_items.append((True, value))
                    else:
                        sort_items.append((True, value))
            return tuple(sort_items)

        # Sort using the key. We apply reverse=True if any top-level sort item is descending.
        # NOTE: True multi-level sorting with mixed ascending/descending in Python requires careful key construction.
        # For this implementation, we assume a stable sort where the primary key dictates the direction.

        # A simpler, though perhaps less efficient, method for mixed ASC/DESC: sort multiple times.
        # However, to meet Rule 7 (single stable sort): 
        # We must ensure the key comparison handles the directionality.

        # We use functools.cmp_to_key for accurate comparison if types are uniform per column.
        from functools import cmp_to_key

        def custom_compare(row1: Dict[str, Any], row2: Dict[str, Any]) -> int:
            for i, (col_name, descending) in enumerate(stmt.order_by):
                val1, type1 = get_sort_key_and_type(row1, col_name, tables)
                val2, type2 = get_sort_key_and_type(row2, col_name, tables)

                # Rule 7: If non-NULL values have different kinds, raise error
                if val1 is not None and val2 is not None and type1 != type2:
                    raise SQLExecutionError(f"Ordering columns must have consistent types in kept rows: {col_name}")

                # NULL handling: NULLs before (ASC) / after (DESC)
                is_null1 = val1 is None
                is_null2 = val2 is None

                if is_null1 and is_null2:
                    continue # Tie
                if is_null1:
                    # NULL sorts first in ASC (return -1), last in DESC (return 1)
                    return -1 if not descending else 1
                if is_null2:
                    # NULL sorts first in ASC (return 1), last in DESC (return -1)
                    return 1 if not descending else -1

                # Standard comparison
                if val1 < val2:
                    return -1 if not descending else 1
                if val1 > val2:
                    return 1 if not descending else -1

            return 0 # Tie across all columns

        filtered_rows.sort(key=cmp_to_key(custom_compare))

    # 3. Limiting (LIMIT n)
    if stmt.limit is not None and stmt.limit >= 0:
        filtered_rows = filtered_rows[:stmt.limit]

    # 4. Projection (Result Construction)
    result = []
    select_cols = stmt.columns

    if select_cols is None: # SELECT *
        # Rule 9: Shallow copy
        for row in filtered_rows:
            result.append(row.copy())
    else: # SELECT col1, col2, ...
        # Rule 9: Construct dict with listed names
        for row in filtered_rows:
            new_row = {}
            for col_name in select_cols:
                # Rule 2: Column missing reads as NULL (None)
                value = row.get(col_name, None)
                new_row[col_name] = value
            result.append(new_row)

    return result


# --- Wrapper Function --- 

def query(sql: str, tables: Dict[str, List[Dict]]) -> List[Dict]:
    """Top-level entry point for running a query."""
    from minisql.parser import parse # Assuming parse is available
    stmt = parse(sql)
    return execute(stmt, tables)

