        select_token = self.consume('KEYWORD', 'SELECT')
        select_list_info = self._parse_select_list()

        # Initialize defaults for the new Select structure
        items: List[Tuple[Any, str]] = []
        columns: Optional[List[str]] = None

        if select_list_info == '*':
