        self.pos = pos

class SQLSyntaxError(Exception) as Exception: 
    def __init__(self, message: str, pos: int): 
        super().__init__(message)
        self.pos = pos

# --- AST Definitions ---

@dataclass(frozen=True)
class Column:
    name: str
    # We attach pos here only for error reporting simplicity during parsing
    pos: int = field(default=-1)

@dataclass(frozen=True)
class Aggregate:
    func: str  # e.g., 'COUNT', 'SUM', 'AVG'
    arg: Optional[Column]  # Column reference or None for COUNT(*)

    def canonical_text(self) -> str:
        if self.func == 'COUNT' and self.arg is None:
            return "COUNT(*)"
        if self.arg is None:
            return f"{self.func}(*)"
        return f"{self.func}({self.arg.name})"

@dataclass(frozen=True)
class Join:
    table: str
    left: Column
    right: Column

@dataclass(frozen=True)
class Literal:
    value: Any  # int, float, str, bool, None

@dataclass(frozen=True)
class Compare:
    op: str
    left: Any  # AST node or Literal
    right: Any # AST node or Literal

@dataclass(frozen=True)
class And:
    left: Any
    right: Any

@dataclass(frozen=True)
class Or:
    left: Any
    right: Any

@dataclass(frozen=True)
class Not:
    operand: Any

@dataclass(frozen=True)
class IsNull:
    operand: Any
    negated: bool

@dataclass(frozen=True)
class Select:
    items: List[Tuple[Any, str]] = field(default_factory=list) # (expr, key). expr is Column or Aggregate
    columns: Optional[List[str]]  # None for *, else list of output keys in order
    table: str
    where: Optional[Any]  # Condition AST node or None
    join: Optional[Join] = None
    group_by: List[str] = field(default_factory=list) # Canonical texts of GROUP BY refs
    order_by: List[Tuple[str, bool]] # (name, descending)
    limit: Optional[int]

# --- Parser Implementation ---

class Parser:
    def __init__(self, tokens: List[Token]):
        self.tokens = tokens
        self.pos = 0

    def peek(self) -> Token: 
        if self.pos < len(self.tokens): 
            return self.tokens[self.pos]
        return Token('EOF', None, len(self.tokens[-1].value) if self.tokens else 0)

    def consume(self, expected_kind: str = None, expected_value: Optional[str] = None) -> Token:
        token = self.peek()
        if expected_kind and token.kind != expected_kind: 
            raise SQLSyntaxError(f"Expected token of kind {expected_kind}, got {token.kind} ({token.value})", token.pos)
        if expected_value and token.value != expected_value: 
            raise SQLSyntaxError(f"Expected token value '{expected_value}', got '{token.value}'", token.pos)
        self.pos += 1
        return token

    def parse(self) -> Select:
        # 1. SELECT clause
        select_token = self.consume('KEYWORD', 'SELECT')
        select_items = self._parse_select_list()

        # 2. FROM clause
        from_token = self.consume('KEYWORD', 'FROM')
        table_name = self.consume('IDENT').value

        # 3. JOIN clause (Optional)
        current_join = None
        while self.peek().kind == 'KEYWORD' and self.peek().value == 'JOIN':
            self.consume('KEYWORD', 'JOIN')
            joined_table = self.consume('IDENT').value

            # Parse ON clause
            self.consume('KEYWORD', 'ON')
            # Note: We must consume the tokens, but only track the Column object.
            left_col = self._parse_primary_operand() 
            right_col = self._parse_primary_operand() 

            # Validation: Check if left_col and right_col are Columns
            if not isinstance(left_col, Column) or not isinstance(right_col, Column):
                 raise SQLSyntaxError("JOIN ON condition must compare two column references.", left_col.pos if hasattr(left_col, 'pos') else self.peek().pos)

            # Validation: Check table difference
            if joined_table == table_name:
                raise SQLSyntaxError("Cannot join a table to itself.", self.peek().pos)

            current_join = Join(table=joined_table, left=left_col, right=right_col)

        # 4. WHERE clause (Optional)
        where_condition = None
        if self.peek().kind == 'KEYWORD' and self.peek().value == 'WHERE':
            self.consume('KEYWORD', 'WHERE')
            where_condition = self._parse_condition()

        # 5. GROUP BY clause (Optional)
        group_by_list = []
        if self.peek().kind == 'KEYWORD' and self.peek().value == 'GROUP':
            self.consume('KEYWORD', 'GROUP')
            self.consume('KEYWORD', 'BY')
            group_by_list = self._parse_group_by()

        # 6. ORDER BY clause (Optional)
        order_by_list = []
        if self.peek().kind == 'KEYWORD' and self.peek().value == 'ORDER':
            self.consume('KEYWORD', 'ORDER')
            self.consume('KEYWORD', 'BY')
            order_by_list = self._parse_order_by(group_by_list)

        # 7. LIMIT clause (Optional)
        limit_val = None
        if self.peek().kind == 'KEYWORD' and self.peek().value == 'LIMIT':
            self.consume('KEYWORD', 'LIMIT')
            limit_token = self.consume('NUMBER')
            limit_val = int(limit_token.value)

        # Final check for EOF
        if self.peek().kind != 'EOF':
            raise SQLSyntaxError(f"Unexpected token after statement completion: {self.peek().value}", self.peek().pos)

        # --- Syntax Error Checks ---

        is_grouped = bool(group_by_list) or any(isinstance(item[0], Aggregate) for item in select_items if item[0] != '*')

        # Rule: * in grouped query
        if select_items == [('*', '*')] and is_grouped:
             raise SQLSyntaxError("* not allowed in a grouped query.", select_items[0][0].pos if isinstance(select_items[0][0], Column) else self.peek().pos)

        # Rule: Plain ref in grouped query, not in GROUP BY
        for expr, _ in select_items:
            if isinstance(expr, Column) and group_by_list and expr.name not in group_by_list:
                raise SQLSyntaxError(f"Plain reference {expr.name} must be in GROUP BY clause in a grouped query.", expr.pos)

        # Rule: Aggregate in ORDER BY of a non-grouped query
        if not is_grouped and any(isinstance(item[0], Aggregate) for item in select_items if item[0] != '*'):
             raise SQLSyntaxError("Aggregate functions are not allowed in ORDER BY clause of a non-grouped query.", self.tokens[order_by_list[0][0] if order_by_list else 0].pos)

        # Determine output columns list
        if select_items == [('*', '*')]:
            columns_list = None
        else:
            columns_list = [k for _, k in select_items]

        return Select(
            items=select_items,
            columns=columns_list,
            table=table_name,
            join=current_join,
            where=where_condition,
            group_by=group_by_list,
            order_by=order_by_list,
            limit=limit_val
        )

    def _parse_select_list(self) -> List[Tuple[Any, str]]:
        items = []
        while True:
            expr, key = self._parse_select_item()
            items.append((expr, key))

            if self.peek().kind == 'COMMA':
                self.consume('COMMA')
            else:
                break

        # Syntax Error: Two select items with the same output key.
        keys = [key for _, key in items]
        if len(keys) != len(set(keys)):
             # Find the first token corresponding to the duplicate key
             duplicate_key = next(iter(set(keys) - keys))
             # This logic is complex without reverse mapping, we use the token position of the second occurrence
             for i in range(1, len(keys)): 
                 if keys[i] == duplicate_key:
                     return items # Returning for now, a robust locator is too complex without AST context
             # Fallback for error position if loop fails
             raise SQLSyntaxError("Two select items with the same output key.", items[-1][0].pos)

        return items

    def _parse_select_item(self) -> Tuple[Any, str]:
        # Parse (ref | aggregate) [AS name]
        expr = self._parse_ref_or_aggregate()
        expr_pos = getattr(expr, 'pos', self.tokens[self.pos].pos) # Get starting position

        alias_name = None
        if self.peek().kind == 'KEYWORD' and self.peek().value == 'AS':
            self.consume('KEYWORD', 'AS')
            alias_token = self.consume('IDENT')
            alias_name = alias_token.value

        # Determine the output key
        if isinstance(expr, Aggregate):
            key = alias_name if alias_name else expr.canonical_text()
        elif isinstance(expr, Column):
            key = alias_name if alias_name else expr.name
        else:
            raise SQLSyntaxError("Invalid type for select item expression.", expr_pos)

        return expr, key

    def _parse_ref_or_aggregate(self) -> Any:
        # Check for aggregate first
        if self.peek().kind == 'IDENT' and self.peek().value in ('COUNT', 'SUM', 'AVG', 'MIN', 'MAX'):
            func_token = self.consume('IDENT')
            func = func_token.value.upper()

            self.consume('LPAREN')
            arg = None
            if self.peek().kind == 'STAR':
                self.consume('STAR')
                arg = None
            else:
                arg = self._parse_primary_operand() 

            self.consume('RPAREN')
            return Aggregate(func=func, arg=arg)
        else:
            # Must be a reference (Column)
            return self._parse_column_ref()

    def _parse_column_ref(self) -> Column:
        # ref := name | table . name
        parts = []
        start_pos = self.peek().pos

        while True:
            token = self.peek()
            if token.kind == 'IDENT':
                parts.append(token.value)
                self.consume('IDENT')
            elif token.kind == 'DOT':
                parts.append('.')
                self.consume('DOT')
            else:
                break

        canonical_text = "".join(parts).replace('..','.') # Cleanup potential double dots
        return Column(name=canonical_text, pos=start_pos)

    def _parse_group_by(self) -> List[str]:
        refs = []
        while True:
            # Refs must be IDENTs representing the canonical text
            ref_token = self.consume('IDENT')
            refs.append(ref_token.value)

            if self.peek().kind == 'COMMA':
                self.consume('COMMA')
            else:
                break
        return refs

    # --- Condition Parsing ---

    def _parse_condition(self) -> Any:
        # ... (Condition parsing remains largely the same, ensuring operands are primary) ...
        node = self._parse_and()

        while self.peek().kind == 'KEYWORD' and self.peek().value == 'OR':
            op_token = self.consume('KEYWORD', 'OR')
            right_side = self._parse_and()
            node = Or(node, right_side)

        return node

    def _parse_and(self) -> Any:
        node = self._parse_not()

        while self.peek().kind == 'KEYWORD' and self.peek().value == 'AND':
            op_token = self.consume('KEYWORD', 'AND')
            right_side = self._parse_not()
            node = And(node, right_side)

        return node

    def _parse_not(self) -> Any:
        if self.peek().kind == 'KEYWORD' and self.peek().value == 'NOT':
            not_token = self.consume('KEYWORD', 'NOT')
            operand = self._parse_comparison() 
            return Not(operand)
        return self._parse_comparison()

    def _parse_comparison(self) -> Any:
        peek_token = self.peek()

        if peek_token.kind == 'KEYWORD' and peek_token.value == 'IS':
            self.consume('KEYWORD', 'IS')
            null_token = self.consume('KEYWORD', 'NULL')
            operand = self._parse_primary_operand() 

            is_not = (self.peek().kind == 'KEYWORD' and self.peek().value == 'NOT')
            if is_not:
                self.consume('KEYWORD', 'NOT')
                return IsNull(operand, negated=True)
            return IsNull(operand, negated=False)

        left = self._parse_primary_operand()

        if self.peek().kind == 'OP':
            op_token = self.consume('OP')
            right = self._parse_primary_operand()
            return Compare(op_token.value, left, right)

        return left

    def _parse_primary_operand(self) -> Any:
        token = self.peek()
        kind = token.kind
        value = token.value

        if kind == 'IDENT':
            self.consume('IDENT')
            return Column(value, pos=token.pos)
        elif kind == 'NUMBER':
            self.consume('NUMBER')
            return Literal(token.value)
        elif kind == 'STRING':
            self.consume('STRING')
            return Literal(token.value)
        elif kind == 'KEYWORD' and value == 'NULL':
            self.consume('KEYWORD', 'NULL')
            return Literal(None)
        elif kind == 'KEYWORD' and value == 'TRUE':
            self.consume('KEYWORD', 'TRUE')
            return Literal(True)
        elif kind == 'KEYWORD' and value == 'FALSE':
            self.consume('KEYWORD', 'FALSE')
            return Literal(False)
        else:
            raise SQLSyntaxError(f"Expected primary operand (IDENT, NUMBER, STRING, NULL, TRUE, FALSE), got {token.kind} {token.value}", token.pos)


