    def _parse_condition(self) -> Any:
        # Start with the lowest precedence: OR
        node = self._parse_and()

        while self.peek().kind == 'KEYWORD' and self.peek().value == 'OR':
            op_token = self.consume('KEYWORD', 'OR')
            right_side = self._parse_and()
            node = Or(node, right_side)

        return node

    def _parse_and(self) -> Any:
        # Next precedence: AND
        node = self._parse_not()

        while self.peek().kind == 'KEYWORD' and self.peek().value == 'AND':
            op_token = self.consume('KEYWORD', 'AND')
            right_side = self._parse_not()
            node = And(node, right_side)

        return node

    def _parse_not(self) -> Any:
