        if self.peek().kind == 'KEYWORD' and self.peek().value == 'NOT':
            not_token = self.consume('KEYWORD', 'NOT')
            operand = self._parse_comparison() # NOT applies to a whole comparison/operand
            return Not(operand)
        return self._parse_comparison()

    def _parse_comparison(self) -> Any:
        # Primary expression: comparison or IsNull
        peek_token = self.peek()

        # Check for IS NULL / IS NOT NULL
        if peek_token.kind == 'KEYWORD' and peek_token.value == 'IS':
            self.consume('KEYWORD', 'IS')
            null_token = self.consume('KEYWORD', 'NULL')
            operand = self._parse_primary_operand() # Operand must precede IS NULL/NOT NULL

            is_not = (self.peek().kind == 'KEYWORD' and self.peek().value == 'NOT')
            if is_not:
                self.consume('KEYWORD', 'NOT')
                return IsNull(operand, negated=True)
            return IsNull(operand, negated=False)

        # Otherwise, parse a standard comparison (operand OP operand)
        left = self._parse_primary_operand()

        if self.peek().kind == 'OP':
            op_token = self.consume('OP')
            right = self._parse_primary_operand()
            return Compare(op_token.value, left, right)

        # If it didn't match a comparison, it must be a standalone operand (which is invalid as a condition)
        # However, in the context of this parser, if it's not a comparison, we treat it as the start of an invalid structure 
        # unless it's a standalone operand that *should* have been part of a comparison.
        # Since the grammar states 'A bare operand is not a condition', we must ensure the structure is valid.
        # If we reach here and it's not a comparison, it means the expression starts with just one operand, which is invalid.
        # We rely on the recursive structure to catch this, but for safety in _parse_comparison, we treat the single operand as the structure.
        # A robust implementation might require the caller (e.g., _parse_and) to check if the resulting node is a valid condition.
        return left

    def _parse_primary_operand(self) -> Any:
        # Handles IDENT, NUMBER, STRING, NULL, TRUE, FALSE
        token = self.peek()
        kind = token.kind
        value = token.value

        if kind == 'IDENT':
            self.consume('IDENT')
            return Column(value)
        elif kind == 'NUMBER':
            self.consume('NUMBER')
            return Literal(value)
        elif kind == 'STRING':
            self.consume('STRING')
            return Literal(value)
        elif kind == 'KEYWORD' and value == 'NULL':
            self.consume('KEYWORD', 'NULL')
            return Literal(None)
        elif kind == 'KEYWORD' and value == 'TRUE':
            self.consume('KEYWORD', 'TRUE')
            return Literal(True)
        elif kind == 'KEYWORD' and value == 'FALSE':
            self.consume('KEYWORD', 'FALSE')
            return Literal(False)
        else:
            raise SQLSyntaxError(f"Expected primary operand (IDENT, NUMBER, STRING, NULL, TRUE, FALSE), got {token.kind} {token.value}", token.pos)


