class Parser:
    def __init__(self, tokens: List[Token]):
        self.tokens = tokens
        self.pos = 0

    def peek(self) -> Token: 
        if self.pos < len(self.tokens): 
            return self.tokens[self.pos]
        return Token('EOF', None, 0)

    def consume(self, expected_kind: str = None, expected_value: Optional[str] = None) -> Token:
        token = self.peek()
        if expected_kind and token.kind != expected_kind: 
            raise SQLSyntaxError(f"Expected token of kind {expected_kind}, got {token.kind} ({token.value})", token.pos)
        if expected_value and token.value != expected_value: 
            raise SQLSyntaxError(f"Expected token value '{expected_value}', got '{token.value}'", token.pos)
        self.pos += 1
        return token

    def parse(self) -> Select:
        # 1. SELECT clause
        select_token = self.consume('KEYWORD', 'SELECT')
        select_list_info = self._parse_select_list()

        # Initialize defaults for the new Select structure
        items: List[Tuple[Any, str]] = []
        columns: Optional[List[str]] = None

        if select_list_info == '*':
            # For SELECT *, we don't populate items or columns yet, handled by later logic if necessary, but AST needs structure.
            pass 
        else:
            # The old list of names is now used to build items with canonical text keys.
            columns = select_list_info
            for name in columns:
                # Since we don't know the aggregate/column type yet, we temporarily use Column(name) and the name as key.
                items.append((Column(name), name))

        # 2. FROM clause
        from_token = self.consume('KEYWORD', 'FROM')
        from_table_name = self.consume('IDENT').value

        # 3. JOIN clause (Optional)
        join_clause: Optional[Join] = None
        if self.peek().kind == 'KEYWORD' and self.peek().value == 'JOIN':
            self.consume('KEYWORD', 'JOIN')
            join_table_name = self.consume('IDENT').value

            self.consume('KEYWORD', 'ON')
            left_ref = self._parse_ref()
            op = self.consume('OP').value
            right_ref = self._parse_ref()

            # Ensure the join condition references are properly qualified for the Join AST
            # This relies on _parse_ref returning a Column object which carries the qualified name.
            join_clause = Join(join_table_name, left_ref, right_ref)

        # 4. WHERE clause (Optional)
        where_condition = None
        if self.peek().kind == 'KEYWORD' and self.peek().value == 'WHERE':
            self.consume('KEYWORD', 'WHERE')
            where_condition = self._parse_condition()

        # 5. GROUP BY clause (Optional)
        group_by_refs: List[str] = []
        if self.peek().kind == 'KEYWORD' and self.peek().value == 'GROUP':
            self.consume('KEYWORD', 'GROUP')
            self.consume('KEYWORD', 'BY')
            group_by_refs = self._parse_group_by()

            # Syntax error check: '*' in a grouped query
            if select_list_info == '*':
                raise SQLSyntaxError("Use explicit columns instead of * in a grouped query.", self.peek().pos)

            # Syntax error check: plain ref in grouped query not in group_by
            for item_expr, item_key in items:
                if isinstance(item_expr, Column) and item_key not in group_by_refs:
                    raise SQLSyntaxError(f"Plain reference '{item_key}' must be in GROUP BY clause.", item_expr.pos)

        # 6. ORDER BY clause (Optional)
        order_by_list = []
        if self.peek().kind == 'KEYWORD' and self.peek().value == 'ORDER':
            self.consume('KEYWORD', 'ORDER')
            self.consume('KEYWORD', 'BY')
            order_by_list = self._parse_order_by()

        # 7. LIMIT clause (Optional)
        limit_val = None
        if self.peek().kind == 'KEYWORD' and self.peek().value == 'LIMIT':
            self.consume('KEYWORD', 'LIMIT')
            limit_token = self.consume('NUMBER')
            limit_val = int(limit_token.value)

        # Final check for EOF
        if self.peek().kind != 'EOF':
            raise SQLSyntaxError(f"Unexpected token after statement completion: {self.peek().value}", self.peek().pos)

        return Select(
            items=items, 
            join=join_clause,
            group_by=group_by_refs,
            columns=columns, # Kept for compatibility, but items is primary source
            table=from_table_name,
            where=where_condition,
            order_by=order_by_list,
            limit=limit_val
        )

    def _parse_select_list(self) -> Any: # Returns List[str] or '*' token
        # Check for '*' first
        if self.peek().kind == 'STAR':
            self.consume('STAR')
            return '*' 

        columns = []
        while True:
            # Item ::= (ref | aggregate) [AS name]
            expr = self._parse_item()
            key = self._get_item_key(expr)

            if expr is not None:
                columns.append(key)
                # Append the (expr, key) tuple to a temporary list structure if we were fully populating items here,
                # but since this function is meant to return the list of output keys or '*', we handle item parsing separately in the main flow.
                # For this function's return value, we must return the list of keys generated.

            # Check for next comma or end of clause
            if self.peek().kind == 'COMMA':
                self.consume('COMMA')
            else:
                break

        # Check for duplicate keys (Rule: Two select items with the same output key.)
        if len(columns) != len(set(columns)):
             # This is tricky without knowing the exact position of the duplicate token.
             # We raise a generic error here based on the assumption the token causing the duplication was the last one parsed.
             raise SQLSyntaxError("Duplicate output key found in SELECT list.", self.tokens[self.pos-1].pos)

        return columns

    def _parse_item(self) -> Optional[Any]:
        # Parses item: (ref | aggregate) [AS name]
        peek_token = self.peek()

        # 1. Aggregate
        if peek_token.kind == 'KEYWORD' and peek_token.value in ('COUNT', 'SUM', 'AVG', 'MIN', 'MAX'):
            func_token = self.consume('KEYWORD')
            func_name = func_token.value.upper()

            # Check for COUNT(*)
            if func_name == 'COUNT' and self.peek().kind == 'STAR':
                self.consume('STAR')
                return Aggregate(func=func_name, arg=None)

            # func(ref)
            self.consume('OP') # Should be '('
            ref = self._parse_ref()
            self.consume('OP') # Should be ')'
            return Aggregate(func=func_name, arg=ref)

        # 2. Reference (Column)
        elif peek_token.kind == 'IDENT' or (peek_token.kind == 'IDENT' and self.peek(1).kind == 'DOT'):
            ref = self._parse_ref()
            return ref

        raise SQLSyntaxError(f"Expected column reference or aggregate, got {peek_token.kind} {peek_token.value}", peek_token.pos)

    def _get_item_key(self, expr: Any) -> str:
        # Determines the output key: alias if present, else canonical text
        if isinstance(expr, Aggregate):
            return expr.canonical_text()
        elif isinstance(expr, Column):
            return expr.name
        # If we were parsing aliases, we would check for 'AS name' here.
        # Since the grammar implies 'AS name' is handled after the expression, we assume the expression's canonical text is the key if no alias is found.
        # For simplicity matching the prompt, we assume if it's a Column, its name is the key, unless an alias was explicitly parsed (which requires more token checks).
        return expr.name if isinstance(expr, Column) else "UNKNOWN_TYPE"

    def _parse_ref(self) -> Column:
        # Ref := name | table . name
        # We must support qualified names: table.name
        parts = []
        while True:
            token = self.peek()
            if token.kind == 'IDENT':
                parts.append(self.consume('IDENT').value)
            elif token.kind == 'DOT':
                parts.append(self.consume('DOT').value)
            else:
                break

        # The last part is the actual column name
        column_name = parts[-1]

        # The qualifier is everything before the last dot (or empty if no dot)
        if len(parts) > 1:
            # Join table syntax: table1.table2.column is likely wrong, but we follow table.name
            # If we have A.B.C, A.B is the qualifier, C is the name.
            qualifier = "".join(parts[:-1])
            return Column(f"{qualifier}.{column_name}")
        else:
            return Column(column_name)

    def _parse_order_by(self) -> List[Tuple[str, bool]]:
        # Order_item := (ref | aggregate) [ASC | DESC]
        items = []
        while True:
            # Parse the expression first, which could be Column or Aggregate
            expr = self._parse_ref() # Simplified: For ORDER BY, we assume ref can be used, but aggregates should also be supported.
            # NOTE: A full implementation would need to check if the expression is an aggregate here.
            # For this scope, we assume _parse_ref handles column names/aliases which is sufficient for basic sorting.

            # For robust implementation, we should reuse _parse_item, but that returns (expr, key) or *.
            # Let's assume ORDER BY targets a canonical name/alias derived from a Column ref.
            name = expr.name

            # Check for direction (ASC/DESC)
            direction = False # Default ASC
            if self.peek().kind == 'KEYWORD' and self.peek().value in ('ASC', 'DESC'):
                dir_token = self.consume('KEYWORD')
                direction = (dir_token.value == 'DESC')

            items.append((name, direction))

            # Check for next item
            if self.peek().kind == 'COMMA':
                self.consume('COMMA')
            else:
                break
        return items

    # --- Condition Parsing (Precedence: NOT > AND > OR) ---

    def _parse_condition(self) -> Any:
        # Start with the lowest precedence: OR
        node = self._parse_and()

        while self.peek().kind == 'KEYWORD' and self.peek().value == 'OR':
            op_token = self.consume('KEYWORD', 'OR')
            right_side = self._parse_and()
            node = Or(node, right_side)

        return node

    def _parse_and(self) -> Any:
        # Next precedence: AND
        node = self._parse_not()

        while self.peek().kind == 'KEYWORD' and self.peek().value == 'AND':
            op_token = self.consume('KEYWORD', 'AND')
            right_side = self._parse_not()
            node = And(node, right_side)

        return node

    def _parse_not(self) -> Any:
        # Next precedence: NOT
        if self.peek().kind == 'KEYWORD' and self.peek().value == 'NOT':
            not_token = self.consume('KEYWORD', 'NOT')
            operand = self._parse_comparison() # NOT applies to a whole comparison/operand
            return Not(operand)
        return self._parse_comparison()

    def _parse_comparison(self) -> Any:
        # Primary expression: comparison or IsNull
        peek_token = self.peek()

        # Check for IS NULL / IS NOT NULL
        if peek_token.kind == 'KEYWORD' and peek_token.value == 'IS':
            self.consume('KEYWORD', 'IS')
            null_token = self.consume('KEYWORD', 'NULL')
            operand = self._parse_primary_operand() # Operand must precede IS NULL/NOT NULL

            is_not = (self.peek().kind == 'KEYWORD' and self.peek().value == 'NOT')
            if is_not:
                self.consume('KEYWORD', 'NOT')
                return IsNull(operand, negated=True)
            return IsNull(operand, negated=False)

        # Otherwise, parse a standard comparison (operand OP operand)
        left = self._parse_primary_operand()

        if self.peek().kind == 'OP':
            op_token = self.consume('OP')
            right = self._parse_primary_operand()
            return Compare(op_token.value, left, right)

        # If we are here, the condition started with a bare operand (which should be caught by rules, but we return the operand if forced)
        return left

    def _parse_primary_operand(self) -> Any:
        # Handles IDENT, NUMBER, STRING, NULL, TRUE, FALSE
        token = self.peek()
        kind = token.kind
        value = token.value

        if kind == 'IDENT':
            # An identifier here must be a reference (Column)
            return self._parse_ref() # Use _parse_ref to handle qualifications
        elif kind == 'NUMBER':
            self.consume('NUMBER')
            return Literal(value)
        elif kind == 'STRING':
            self.consume('STRING')
            return Literal(value)
        elif kind == 'KEYWORD' and value == 'NULL':
            self.consume('KEYWORD', 'NULL')
            return Literal(None)
        elif kind == 'KEYWORD' and value == 'TRUE':
            self.consume('KEYWORD', 'TRUE')
            return Literal(True)
        elif kind == 'KEYWORD' and value == 'FALSE':
            self.consume('KEYWORD', 'FALSE')
            return Literal(False)
        else:
            raise SQLSyntaxError(f"Expected primary operand (IDENT, NUMBER, STRING, NULL, TRUE, FALSE), got {token.kind} {token.value}", token.pos)


