        from_token = self.consume('KEYWORD', 'FROM')
        from_table_name = self.consume('IDENT').value

        # 3. JOIN clause (Optional)
        join_clause: Optional[Join] = None
        if self.peek().kind == 'KEYWORD' and self.peek().value == 'JOIN':
            self.consume('KEYWORD', 'JOIN')
            join_table_name = self.consume('IDENT').value

            self.consume('KEYWORD', 'ON')
            left_ref = self._parse_ref()
            op = self.consume('OP').value
            right_ref = self._parse_ref()

            # Ensure the join condition references are properly qualified for the Join AST
            join_clause = Join(join_table_name, left_ref, right_ref)

