from dataclasses import dataclass
from typing import List, Optional, Dict, Any, Union, Tuple

# --- Exceptions ---

class MachineError(Exception):
    """Base class for machine errors."""
    pass

class InvalidTransition(MachineError):
    """Raised by fire when no transition for the event leaves the current state."""
    def __init__(self, state: str, event: str): 
        super().__init__(f"InvalidTransition: No transition found for event '{event}' in state '{state}'.")
        self.state = state
        self.event = event

class GuardRejected(MachineError):
    """Raised by fire when every transition for the event is rejected by its guard."""
    def __init__(self, state: str, event: str): 
        super().__init__(f"GuardRejected: All transitions for event '{event}' in state '{state}' were rejected by guards.")
        self.state = state
        self.event = event

# --- Data Classes ---

@dataclass
class State:
    name: str
    on_enter: Optional[callable] = None
    on_exit: Optional[callable] = None

@dataclass
class Transition:
    event: str
    source: Union[str, List[str], Tuple[str, ...]]
    target: Optional[Union[str, None]]
    guard: Optional[callable] = None
    action: Optional[callable] = None

@dataclass
class Event:
    name: str
    source: str
    target: str
    data: Dict[str, Any]

# --- Machine Class ---

class Machine:
    """Finite State Machine implementation."""
    def __init__(self, states: Union[List[State], List[str]], transitions: List[Transition], initial: str, context: Optional[Any] = None):
        self.context = context
        self.initial = initial
        self.states_map: Dict[str, State] = {}
        self.all_states_names: set = set()
        self.transitions: List[Transition] = transitions
        self.history: List[Tuple[str, str, str]] = []
        self._is_running = False

        # 1. Validate States
        state_names = set()
        state_objects: Dict[str, State] = {}

        for item in states:
            name: str
            if isinstance(item, str):
                name = item
                state_obj = State(name=name) # Plain name
            elif isinstance(item, State):
                name = item.name
                state_obj = item
            else:
                raise TypeError("States must be State objects or strings.")

            if name in state_names:
                raise ValueError(f"Two states share the name: {name}.")
            state_names.add(name)
            state_objects[name] = state_obj

        self.states_map = state_objects
        self.all_states_names = state_names

        # 2. Validate Initial State
        if initial not in self.all_states_names:
            raise ValueError(f"Initial state '{initial}' is not a defined state.")

        # 3. Validate Transitions
        for t in transitions:
            # Validate Source
            sources_to_check = []
            if isinstance(t.source, str):
                sources_to_check = [t.source]
            elif isinstance(t.source, (list, tuple)):
                sources_to_check = t.source

            for src in sources_to_check:
                if src not in self.all_states_names and src != '*':
                    raise ValueError(f"Transition source '{src}' references an undefined state.")

            # Validate Target
            if t.target is not None:
                if t.target not in self.all_states_names:
                    raise ValueError(f"Transition target '{t.target}' references an undefined state.")

        # Initialization
        self.state = initial
        self.history = []
        self._is_running = False

    def reset(self):
        """Sets the state back to initial and clears history. Runs no hooks."""
        self.state = self.initial
        self.history.clear()
        self._is_running = False

    def available_events(self) -> list[str]:
        """Returns the sorted, de-duplicated names of the events that have at least one transition from the current state, ignoring guards."""
        events = set()
        current_state = self.state

        for t in self.transitions:
            source_match = False
            sources = t.source

            if isinstance(sources, str):
                if sources == '*' or sources == current_state:
                    source_match = True
            elif isinstance(sources, (list, tuple)):
                if any(src == '*' or src == current_state for src in sources):
                    source_match = True

            if source_match:
                events.add(t.event)

        return sorted(list(events))

    def can_fire(self, event: str, **data) -> bool:
        """Checks if fire with the same arguments would take a transition now. Calls guards only, no other hooks, no exceptions for InvalidTransition/GuardRejected."""
        candidates = []
        current_state = self.state

        # 1. Find candidates matching event and current state, in order
        for t in self.transitions:
            if t.event != event: 
                continue

            source_match = False
            sources = t.source

            if isinstance(sources, str):
                if sources == '*' or sources == current_state:
                    source_match = True
            elif isinstance(sources, (list, tuple)):
                if any(src == '*' or src == current_state for src in sources):
                    source_match = True

            if source_match: 
                candidates.append(t)

        # 3. Evaluate guards in candidate order
        for t in candidates:
            if t.guard is None:
                return True # No guard, transition is valid
            try:
                # Guards must not have side effects, so we call them with the machine instance
                if t.guard(self, Event(name=event, source=current_state, target='*')):
                    return True
            except Exception:
                # If a guard raises an exception, we treat it as a rejection for safety, though specification implies guards should be pure.
                continue

        return False

    def fire(self, event: str, **data) -> str:
        """Takes one transition and returns the new current state, following the 7-step protocol."""
        if self._is_running: 
            raise MachineError("Cannot fire while another fire call is still running.")

        self._is_running = True
        original_state = self.state
        transition_taken = False
        final_target_state = original_state

        # 2. Create data context
        event_context = Event(name=event, source=original_state, target='*') # Target is placeholder here
        event_context.data = data.copy()

        # 1. Candidates
        candidates = []
        for t in self.transitions:
            if t.event != event: 
                continue

            source_match = False
            sources = t.source
            if isinstance(sources, str):
                if sources == '*' or sources == original_state:
                    source_match = True
            elif isinstance(sources, (list, tuple)):
                if any(src == '*' or src == original_state for src in sources):
                    source_match = True

            if source_match:
                candidates.append(t)

        if not candidates:
            self._is_running = False
            raise InvalidTransition(original_state, event)

        # 3. Guard Evaluation
        chosen_transition: Optional[Transition] = None
        for t in candidates:
            if t.guard is None:
                chosen_transition = t
                break
            try:
                # Guard evaluation. Note: event object passed here might not have the final target yet, but that is fine for guard logic.
                if t.guard(self, event_context):
                    chosen_transition = t
                    break
            except Exception:
                # Exception during guard evaluation implies rejection for safety in this phase
                pass

        if chosen_transition is None:
            self._is_running = False
            raise GuardRejected(original_state, event)

        # --- Transition Logic Begins (State change potential) ---
        t = chosen_transition
        new_state = original_state

        try:
            # 4. Normal Transition Logic
            if t.target is not None:
                # Normal transition
                new_state = t.target

                # Run on_exit (current state)
                state_exit_hook = self.states_map.get(original_state)
                if state_exit_hook and state_exit_hook.on_exit:
                    state_exit_hook.on_exit(self, event_context)

                # Run transition action
                if t.action:
                    t.action(self, event_context)

                # Set state and append to history
                self.state = new_state
                self.history.append((original_state, event, new_state))

                # Run on_enter (target state)
                target_state_hook = self.states_map.get(new_state)
                if target_state_hook and target_state_hook.on_enter:
                    target_state_hook.on_enter(self, event_context)

                # Run listeners
                for listener in self._listeners:
                    listener(original_state, event_context, new_state)

            # 5. Internal Transition Logic (target=None)
            else: # t.target is None
                # Runs only action, records history, calls listeners; state stays the same.

                # Run transition action
                if t.action:
                    t.action(self, event_context)

                # Record history
                self.history.append((original_state, event, original_state))

                # Run listeners
                for listener in self._listeners:
                    listener(original_state, event_context, original_state)

            transition_taken = True
            final_target_state = self.state

        except Exception as e:
            # 6. Exception propagation
            # If exception came from guard, on_exit, action, state/history are unchanged.
            # If it came from on_enter or listener, state/history have already changed.
            # We let the exception propagate.
            raise e
        finally:
            # 7. Clean up running state
            self._is_running = False

        return final_target_state

    # Helper for listeners (must be added to __init__ if not there)
    def __init__(self, states: Union[List[State], List[str]], transitions: List[Transition], initial: str, context: Optional[Any] = None):
        # ... (existing initialization code) ...
        self._listeners: List[callable] = [] # Add this initialization
        # ...

    def on_transition(self, listener: callable):
        """Adds a listener that is called after every transition."""
        self._listeners.append(listener)

