from typing import List

class TicTacToe:
    def __init__(self, board: str = '.........'):
        self.board: str = board
        self._validate_board(board)
        self._player = self._determine_player(board)

    def _validate_board(self, board: str):
        if len(board) != 9:
            raise ValueError("TicTacToe board must be 9 characters long.")

        counts = {'X': 0, 'O': 0, '.': 0}
        for char in board:
            if char not in counts:
                raise ValueError("TicTacToe board must only contain 'X', 'O', or '.'")
            counts[char] += 1

        # X must have the same number of marks as O or one more.
        if not (counts['X'] == counts['O'] or counts['X'] == counts['O'] + 1):
            raise ValueError("Impossible piece counts on the board.")

    def _determine_player(self, board: str) -> str: 
        counts = {'X': 0, 'O': 0, '.': 0}
        for char in board:
            if char in counts:
                counts[char] += 1

        # X always moves first.
        if counts['X'] == counts['O']:
            return 'X'
        elif counts['X'] == counts['O'] + 1:
            return 'O'
        else:
            # This case should be caught by _validate_board, but for robustness:
            raise ValueError("Could not determine current player from board state.")

    def moves(self) -> List[int]:
        if self.is_over():
            return []

        # Legal moves are any empty cell ('.') index
        return [i for i, char in enumerate(self.board) if char == '.']

    def play(self, move: int) -> 'TicTacToe':
        if self.is_over():
            raise ValueError("Cannot make a move, the game is over.")
        if not (0 <= move <= 8) or self.board[move] != '.':
            raise ValueError("Illegal move.")

        # Create new board string immutably
        new_board_list = list(self.board)
        new_board_list[move] = self.board[move] if self.board[move] != '.' else self._get_player_char(self._player)

        # Correcting the logic: the character at the move index must be replaced by the current player's mark.
        # Since we check for '.', the character must be '.'
        new_board_list[move] = self._get_player_char(self._player)
        new_board = "".join(new_board_list)

        # Determine next player
        next_player = 'O' if self._player == 'X' else 'X'

        # Create the new state
        new_state = TicTacToe(new_board)
        # The new state must correctly identify the next player. The constructor handles this by counting.
        return new_state

    def _get_player_char(self, player: str) -> str:
        return player

    def winner(self) -> str | None:
        # Check rows
        for i in range(3):
            row = self.board[i*3:i*3+3]
            if row[0] == row[1] == row[2] != '.':
                return row[0]

        # Check columns
        for j in range(3):
            col = [self.board[i*3 + j] for i in range(3)]
            if col[0] == col[1] == col[2] != '.':
                return col[0]

        # Check diagonals
        # Top-left to bottom-right (0, 4, 8)
        diag1 = [self.board[i*3 + i] for i in range(3)]
        if diag1[0] == diag1[1] == diag1[2] != '.':
            return diag1[0]

        # Top-right to bottom-left (2, 4, 6)
        diag2 = [self.board[i*3 + (2 - i) for i in range(3)] for i in range(3)]
        diag2 = [self.board[2-i]*3 + i for i in range(3)] # This indexing is complex for a flat string, let's re-evaluate diagonals for 0-8 string

        # Re-evaluating diagonals based on 0-8 indices:
        # TL-BR: (0, 4, 8)
        if self.board[0] == self.board[4] == self.board[8] and self.board[0] != '.':
            return self.board[0]
        # TR-BL: (2, 4, 6)
        if self.board[2] == self.board[4] == self.board[6] and self.board[2] != '.':
            return self.board[2]

        return None

    def is_over(self) -> bool:
        return self.winner() is not None or not any(c == '.' for c in self.board)

    def __str__(self) -> str:
        # Rows are 3 chars each
        rows = []
        for i in range(3):
            rows.append(self.board[i*3 : i*3 + 3])
        return '\n'.join(rows) # Wait, the requirement is no trailing newline, so just '\n'.join

    @classmethod
    def from_moves(cls, moves: List[int]) -> 'TicTacToe':
        current_board = '.........'

        for i, move in enumerate(moves):
            # Determine player for this move based on how many moves have been played so far (i)
            # X moves first (i=0, 2, 4...), O moves second (i=1, 3, 5...)
            player_char = 'X' if i % 2 == 0 else 'O'

            # Simulate play on the current_board
            if not (0 <= move <= 8) or current_board[move] != '.':
                raise ValueError("Illegal move encountered during sequence playback.")

            # Apply move
            board_list = list(current_board)
            board_list[move] = player_char
            current_board = "".join(board_list)

        # Construct final state. The constructor handles final validation.
        return cls(current_board)
