from typing import List, Tuple

class ConnectFour:
    """Represents the Connect Four board game state."""
    def __init__(self, columns: int = 7, rows: int = 6):
        if columns < 1 or rows < 1:
            raise ValueError("Columns and rows must be at least 1.")
        self.columns = columns
        self.rows = rows
        # Initialize board with '.' characters. Board[row][column]
        self._board = [['.' for _ in range(columns)] for _ in range(rows)]

    def _check_win(self, player: str) -> bool:
        # Check horizontal wins
        for r in range(self.rows):
            for c in range(self.columns - 3):
                if all(self._board[r][c+i] == player for i in range(4)):
                    return True

        # Check vertical wins
        for c in range(self.columns):
            for r in range(self.rows - 3):
                if all(self._board[r+i][c] == player for i in range(4)):
                    return True

        # Check diagonal (top-left to bottom-right) wins
        for r in range(self.rows - 3):
            for c in range(self.columns - 3):
                if all(self._board[r+i][c+i] == player for i in range(4)):
                    return True

        # Check diagonal (top-right to bottom-left) wins
        for r in range(self.rows - 3):
            for c in range(3, self.columns):
                if all(self._board[r+i][c-i] == player for i in range(4)):
                    return True

        return False

    def moves(self) -> List[int]:
        """Returns a list of legal column moves in ascending order."""
        legal_moves = []
        for c in range(self.columns):
            # A move is legal if the column is not full
            if self._board[self.rows - 1][c] != '.' or self._board[0][c] == '.':
                # Check if the top row of the column is empty
                # Since pieces fall to the lowest empty cell, we check if the column is full
                is_full = True
                for r in range(self.rows):
                    if self._board[r][c] == '.':
                        is_full = False
                        break
                if not is_full:
                    legal_moves.append(c)
        return legal_moves

    def _get_next_empty_row(self, col: int) -> int:
        """Returns the row index (0=bottom) where a piece will fall in the given column."""
        for r in range(self.rows):
            if self._board[r][col] == '.':
                return r
        # Should not happen if moves() is checked correctly
        raise ValueError("Column is full.")

    def play(self, move: int) -> 'ConnectFour':
        """Returns a new state with the move made. Raises ValueError for illegal moves."""
        if move not in self.moves():
            raise ValueError("Illegal move.")

        # Create a deep copy of the current state
        new_board = [row[:] for row in self._board]
        new_state = ConnectFour(self.columns, self.rows)
        new_state._board = new_board

        # Determine player ('X' always moves first in the context of search, 
        # but ConnectFour state needs to track whose turn it is. 
        # We assume the caller manages player turn logic, so we need to infer it.
