    """Negamax search with alpha-beta pruning."""
    nodes_examined = 1 # Count the current node

    if state.is_over():
        # Terminal State Scoring
        winner = state.winner()
        if winner is None:
            # Draw
            return SearchResult(score=0.0, move=None, nodes=nodes_examined)

        if winner == state.player:
            # Win for current player (scorer)
            # A quicker win scores higher: 1000 - ply
            return SearchResult(score=float(1000 - ply), move=None, nodes=nodes_examined)
        else:
            # Loss for current player (scorer)
            # A quicker loss scores lower (more negative): -(1000 - ply)
            return SearchResult(score=float(-(1000 - ply)), move=None, nodes=nodes_examined)

    if depth is not None and ply >= depth:
        # Depth limit reached
        if evaluate: 
            # If evaluate is provided, use it. Otherwise, score 0.
            score = evaluate(state)
