class Calendar:
    """Holds one-off events and recurring series."""
    def __init__(self):
        # Stores Event objects and Recurring objects
        self._items: List[Any] = []

    def add(self, item: Any):
        """Adds an Event or a Recurring series."""
        if isinstance(item, (Event)): # Assuming Recurring is defined elsewhere but we check for known types
            self._items.append(item)
        # Since Recurring is in cal/recurrence.py, we assume it's available or handle it generically if possible.
        # Based on the requirements, we only explicitly check for Event here, and rely on the caller to ensure correct types.
        elif hasattr(item, 'occurrences'): # A heuristic check for Recurring type
            self._items.append(item)
        else:
            raise TypeError("Item added to Calendar must be an Event or a Recurring series.")

    def events_between(self, start: datetime, end: datetime) -> List[Event]:
        """Returns a list of every event that overlaps [start, end), sorted by (start, end, title)."""
        all_events: List[Event] = []

        # Collect all relevant events
        for item in self._items:
            if isinstance(item, Event):
                if self._overlaps_interval(item.start, item.end, start, end):
                    all_events.append(item)
            # We must assume Recurring objects have an occurrences method that respects the window
            elif hasattr(item, 'occurrences') and callable(item.occurrences):
                # The occurrences method must return a list of Event objects
                for event in item.occurrences(start, end):
                    # Although occurrences should already be within the window if implemented correctly,
                    # we ensure we only add valid Event objects.
                    if isinstance(event, Event):
                        all_events.append(event)

        # Sort by (start, end, title)
        all_events.sort(key=lambda e: (e.start, e.end, e.title))
        return all_events

    def events_for(self, person: str, start: datetime, end: datetime) -> List[Event]:
        """Returns the list of events restricted to those whose attendees include 'person'."""
        all_events = self.events_between(start, end)
        return [e for e in all_events if person in e.attendees]

    @staticmethod
    def _overlaps_interval(s1: datetime, e1: datetime, s2: datetime, e2: datetime) -> bool:
        """Helper to check if [s1, e1) overlaps [s2, e2)."""
        # Overlap occurs if s1 < e2 AND s2 < e1
        return s1 < e2 and s2 < e1

