            if current.kind == 'EOF':
                raise JSONError("Unexpected end of input while expecting a value or token", current.line, current.column)
            # Should not happen if EOF is the last token
            raise JSONError("Unexpected token at end of input", current.line, current.column)

        # Rule: Anything but whitespace after the top-level value
        # Since the scanner ignores whitespace between tokens, we only check if EOF follows immediately.
        if self.current_token().kind != 'EOF':
            eof_token = self.tokens[-1] # Assuming EOF is the last token
            raise JSONError("Unexpected characters after the top-level JSON value", eof_token.line, eof_token.column)

        return result

    def parse_value(self) -> Any:
        token = self.current_token()

        if token.kind == 'STRING':
            self.consume('STRING')
            return token.value
        elif token.kind == 'NUMBER':
            self.consume('NUMBER')
            try:
                # Handle -0 being int 0
                if token.value == '-0':
                    return 0
                return float(token.value) if '.' in token.value or 'e' in token.value.lower() else int(token.value)
            except ValueError:
                # This should technically be caught by the scanner, but as a safeguard
                raise JSONError("Invalid number format", token.line, token.column)
        elif token.kind == 'TRUE':
            self.consume('TRUE')
            return True
        elif token.kind == 'FALSE':
            self.consume('FALSE')
            return False
        elif token.kind == 'NULL':
            self.consume('NULL')
            return None
        elif token.kind == '{':
            return self.parse_object()
        elif token.kind == '[':
            return self.parse_array()
        else:
            # Rule: Error if token cannot appear where it is
            raise JSONError(f"Unexpected token '{token.kind}'", token.line, token.column)

    def parse_array(self) -> List[Any]:
        self.consume('[')
        arr: List[Any] = []

        if self.current_token().kind == ']':
            self.consume(']')
            return arr # Empty array

        while True:
            # Parse element
            value = self.parse_value()
            arr.append(value)

            # Check for comma or closing bracket
            next_token = self.current_token()
            if next_token.kind == ']':
                self.consume(']')
                break
            elif next_token.kind == ',':
                self.consume(',')
            else:
                # Trailing comma error or missing comma
                raise JSONError("Expected ',' or ']' in array", next_token.line, next_token.column)

        return arr

    def parse_object(self) -> Dict[str, Any]:
        self.consume('{')
        obj: Dict[str, Any] = {}

        if self.current_token().kind == '}':
            self.consume('}')
            return obj # Empty object

        while True:
            # 1. Parse Key (must be a string)
            key_token = self.current_token()
            if key_token.kind != 'STRING':
                # Missing colon/value error or invalid key type
                raise JSONError("Object key must be a string", key_token.line, key_token.column)

            key = self.consume('STRING').value

            # 2. Consume Colon
            self.consume(':')

            # 3. Parse Value
            value = self.parse_value()

            # Dictionary key uniqueness rule: a repeated key keeps its last value
            obj[key] = value

            # Check for comma or closing brace
            next_token = self.current_token()
            if next_token.kind == '}':
                self.consume('}')
                break
            elif next_token.kind == ',':
                self.consume(',')
            else:
                # Trailing comma error or missing comma
                raise JSONError("Expected ',' or '}' in object", next_token.line, next_token.column)

        return obj

def loads(text: str) -> Any:
    """Parses a JSON string into a Python object."""
    if not text.strip():
        # Empty text case, should result in EOF at line 1, column 1 if tokenized correctly
        # If the scanner produces an empty list for empty input, we handle it here.
        # Assuming tokenizer handles empty string by returning ['EOF']
        try:
            tokens = tokenize(text)
            if not tokens: # Truly empty input
                raise JSONError("Empty input string", 1, 1)
        except NotImplementedError:
            # Fallback if tokenizer isn't available for testing structure
            return None 

    tokens = tokenize(text)

    # Ensure the token list ends with EOF
    if tokens and tokens[-1].kind != 'EOF':
         # This should be caught by the parser's final check, but good to verify here.
         raise JSONError("Missing EOF token at the end of the text", tokens[-1].line, tokens[-1].column)

    parser = Parser(tokens)
    return parser.parse()

