        '!=': lambda v, constraint: v != constraint,
        '>=': lambda v, constraint: v >= constraint,
        '<=': lambda v, constraint: v <= constraint,
        '>': lambda v, constraint: v > constraint,
        '<': lambda v, constraint: v < constraint,
        '^': lambda v, constraint: v >= constraint and v < _next_major_bump(constraint),
        '~': lambda v, constraint: v >= constraint and v < _next_minor_bump(constraint),
    }

    def __init__(self, spec: str):
        self._constraints = self._parse_spec(spec)

    def _parse_spec(self, spec: str) -> list[tuple[str, Version]]:
        if not spec: 
            return []

        # Regex to capture constraint: optional operator, version
        # Operators: ==, !=, >=, <=, >, <, ^, ~
        # Version: MAJOR.MINOR.PATCH (digits only, no leading zeros unless 0)
        constraint_pattern = r'([=<>!~^]+)?\s*(\d+\.\d+\.\d+)'

        # Split by comma, then find all valid constraints in each segment
        all_constraints = []
        segments = [s.strip() for s in spec.split(',')] 

        for segment in segments:
            segment = segment.strip()
            if not segment:
                continue

            match = re.match(r'\s*([=<>!~^]+)?\s*(\d+\.\d+\.\d+)', segment) # Adjusted regex to capture leading whitespace and operator
            if not match:
                raise ValueError(f"Invalid constraint format in spec: '{segment}'")

            op_str = match.group(1) or "=="
            version_str = match.group(2)

            # Handle '*' case separately as it's not captured by version pattern
            if segment == "*":
                 all_constraints.append(('*', None))
                 continue

            try:
                constraint_version = Version(version_str)

                # Handle default equality if operator is missing but format suggests version
                if op_str is None:
                    op_str = "=="

                if op_str not in self._OP_MAP:
                     raise ValueError(f"Unknown operator '{op_str}'")

                all_constraints.append((op_str, constraint_version))
            except ValueError as e:
                raise ValueError(f"Bad version or constraint in spec '{segment}': {e}")

        return all_constraints

    def __str__(self) -> str:
        # Reconstruct string without whitespace
        parts = []
        for op, v in self._constraints:
            if op == '*':
                parts.append('*')
            else:
                parts.append(f"{op}{v}")
        return "".join(parts)

    def contains(self, v: Version) -> bool:
        for op, constraint_v in self._constraints:
            if op == '*':
                continue

            if op in ('>', '<', '>=', '<=', '==', '!='):
                if not self._OP_MAP[op](v, constraint_v):
                    return False
            elif op == '^':
                if not self._OP_MAP[op](v, constraint_v):
                    return False
            elif op == '~':
                if not self._OP_MAP[op](v, constraint_v):
                    return False
        return True

    def __contains__(self, v: Version) -> bool:
        return self.contains(v)

# --- Helper functions for caret (^) and tilde (~) ranges ---

def _next_major_bump(v: Version) -> Version:
    # ^1.2.3 -> <2.0.0
    # ^0.2.3 -> <0.3.0
    # ^0.0.3 -> <0.0.4
    # ^0.0.0 -> <0.0.1
    if v.major > 0:
        return Version(f"{v.major + 1}.0.0")
    else:
        # Major is 0 (e.g., 0.2.3)
        if v.minor > 0:
            return Version(f"0.{v.minor + 1}.0")
        else:
            # Minor is 0 (e.g., 0.0.3)
            return Version(f"0.0.{v.patch + 1}")

def _next_minor_bump(v: Version) -> Version:
    # ~1.2.3 -> <1.3.0
    # ~0.2.3 -> <0.3.0
    # ~0.0.3 -> <0.0.4 (This is technically patch bump for ~0.0.x, but spec implies minor bump if minor > 0)
    # Standard interpretation: ~1.2.3 means >=1.2.3, <1.(2+1).0
    if v.patch > 0:
         # For 0.0.x, we treat it like a patch bump constraint for simplicity based on common semver range logic, although the prompt is ambiguous for 0.0.x.
         # Following the prompt example: ~1.2.3 is >=1.2.3, <1.3.0 (Minor bump)
        if v.minor > 0:
             return Version(f"{v.major}.{v.minor + 1}.0")
        else:
             # If minor is 0 (e.g. 0.0.3), the next minor bump is 0.1.0
             return Version(f"{v.major}.1.0")
    else:
        # Patch is 0 (e.g., 1.2.0 or 0.0.0)
        return Version(f"{v.major}.{v.minor + 1}.0")

# Re-implementing logic for ^0.0.0 to <0.0.1 explicitly if needed, but the helper functions above should cover it based on the rule interpretation.
# For ^0.0.0, _next_major_bump(0.0.0) -> 0.0.1 (since major=0, minor=0, patch=0, falls into last case: 0.0.(0+1) = 0.0.1)
# For ~0.0.0, _next_minor_bump(0.0.0) -> 0.1.0 (since patch=0, falls into last case: 0.(0+1).0 = 0.1.0)

