from typing import Dict, Optional, List, Any
from resolve.versions import Version, Range

class PackageIndex:
    """
    Stores all known package versions and their dependencies.
    """
    def __init__(self):
        # Structure: {package_name: {version_object: {dependency_name: Range_object, ...}, ...}}
        self._index: Dict[str, Dict[Version, Dict[str, Range]]] = {}

    def add(self, name: str, version_str: str, requires: Optional[Dict[str, str]] = None) -> None:
        """
        Adds a release to the index.

        :param name: Name of the package.
        :param version_str: Canonical version string (e.g., "1.2.3").
        :param requires: Dictionary mapping dependency names to spec strings.
        :raises ValueError: If version or spec is invalid, or if release already exists.
        """
        try:
            version = Version(version_str)
        except ValueError as e:
            raise ValueError(f"Invalid version '{version_str}': {e}")

        if name not in self._index:
            self._index[name] = {}

        if version in self._index[name]:
            raise ValueError(f"Release {name} version {version_str} already exists.")

        parsed_requirements: Dict[str, Range] = {}
        if requires:
            for dep_name, spec_str in requires.items():
                try:
                    parsed_requirements[dep_name] = Range(spec_str)
                except ValueError as e:
                    raise ValueError(f"Invalid requirement spec for {name} dependency {dep_name} ('{spec_str}'): {e}")

        self._index[name][version] = parsed_requirements

    def versions(self, name: str) -> List[Version]:
        """
        Returns the list of known Versions for a package, newest first.
        """
        if name not in self._index:
            return []

        # Sort by version object (which implements numerical comparison) in descending order
        versions_list = list(self._index[name].keys())
        versions_list.sort(reverse=True)
        return versions_list

    def requirements(self, name: str, version: Version) -> Dict[str, Range]:
        """
        Returns a dict mapping each dependency name to its Range for a specific Version.

        :raises KeyError: If the specified package/version does not exist.
        """
        if name not in self._index:
            raise KeyError(f"Package {name} is not in the index.")
        if version not in self._index[name]:
            raise KeyError(f"Version {version} of package {name} is not known.")
        return self._index[name][version]

    @classmethod
    def from_dict(cls, data: Dict[str, Dict[str, Dict[str, str]]]) -> 'PackageIndex':
        """
        Builds an index from a dictionary structure.

        Data structure expected: {name: {version_str: {dep: spec, ...}, ...}, ...}
        """
        index = cls()
        for name, versions_data in data.items():
            for version_str, requirements in versions_data.items():
                try:
                    version = Version(version_str)
                except ValueError:
                    # Skip malformed versions in input data gracefully, or raise if strictness is needed
                    continue 

                parsed_requirements: Dict[str, Range] = {}
                valid_entry = True
                for dep_name, spec_str in requirements.items():
                    try:
                        parsed_requirements[dep_name] = Range(spec_str)
                    except ValueError:
                        print(f"Warning: Skipping invalid requirement spec for {name}@{version_str} dependency {dep_name}")
                        valid_entry = False
                        break

                if valid_entry:
                    index._index[name][version] = parsed_requirements
        return index
