class ResolutionError(Exception):
    def __init__(self, package: str, explanation: str):
        self.package = package
        self.explanation = explanation
        super().__init__(explanation)

    def __str__(self):
        return self.explanation

from .versions import Version, Range
from .index import PackageIndex

def _get_constraints(index: PackageIndex, selected: dict, package_name: str, root_requirements: dict) -> list[tuple[str, Range]]:
    """Gathers all constraints for package_name in selection order."""
    constraints = []
    # 1. Root requirement
    if package_name in root_requirements:
        spec = root_requirements[package_name]
        try:
            constraints.append( ( '<root>', Range(spec) ) )
        except ValueError as e:
            # This case should ideally be caught before calling resolve, but safety first
            raise ValueError(f"Bad root requirement spec for {package_name}: {spec}") from e

    # 2. Requirements from selected packages
    for req_name, req_version in selected.items():
        if req_name in index.requirements(package_name, req_version):
            range_obj = index.requirements(package_name, req_version)[req_name]
            constraints.append( ( f"{req_name} {req_version}", range_obj ) )
    return constraints

def resolve(index: PackageIndex, requirements: dict[str, str]) -> dict[str, Version]:
    """Resolves package dependencies using a depth-first search."""

    # Initial setup
    root_order = sorted(requirements.keys())

    # State variables (modified during search)
    # order: list of package names to process, maintained in selection order
    order: list[str] = root_order[:] 
    # selected: dict mapping package name to its selected Version
    selected: dict[str, Version] = {}
    # selection_log: list of (name, version) tuples in order of selection
    selection_log: list[tuple[str, Version]] = []

    def backtrack(current_order: list[str], current_selected: dict[str, Version], current_log: list[tuple[str, Version]]) -> dict[str, Version] | None:
        """Recursive DFS solver."""

        # 1. Find the next package to process
        next_package = None
        try:
            next_package = next(pkg for pkg in current_order if pkg not in current_selected)
        except StopIteration:
            # Success: all packages in order have been selected
            return current_selected

        # 2. Gather constraints
        constraints_info = _get_constraints(index, current_selected, next_package, requirements)

        # 3. Get candidates (newest first)
        all_versions = index.versions(next_package)
        if not all_versions:
            # Failure case 1: No versions known
            explanation = f"cannot resolve {next_package}\n" + "  no versions of {next_package} are known" 
            raise ResolutionError(next_package, explanation)

        # 4. Iterate through candidates
        for candidate_version in all_versions:

            # --- Check Acceptability ---
            is_acceptable = True
            version_exclusions = []
            dependency_conflicts = {}

            # a. Check constraints (version compatibility)
            for requirer, constraint_range in constraints_info:
                if not constraint_range.contains(candidate_version):
                    is_acceptable = False
                    version_exclusions.append(f"  {requirer} requires {next_package} {constraint_range} (fails for {candidate_version})")

            if not is_acceptable:
                # If any constraint fails, this candidate is out. Record exclusion reason.
                # Note: The prompt requires a specific format for this.
                # We must construct the failure report based on the *first* constraint that fails.

                # Re-iterate constraints to find the first one that fails, as required by error format.
                first_failing_constraint = None
                for requirer, constraint_range in constraints_info:
                    if not constraint_range.contains(candidate_version):
                        first_failing_constraint = (requirer, constraint_range)
                        break

                if first_failing_constraint:
                    requirer, constraint_range = first_failing_constraint
                    # Store the specific exclusion reason for later error reporting if this branch leads to failure
                    dependency_conflicts[f"ConstraintFailure_{candidate_version}"] = f"  {requirer} requires {next_package} {constraint_range}"

                continue # Try next candidate

            # b. Check dependencies against already selected packages
            candidate_deps = index.requirements(next_package, candidate_version)
            for dep_name, dep_range in candidate_deps.items():
                if dep_name in current_selected:
                    selected_version = current_selected[dep_name]
                    if not dep_range.contains(selected_version):
                        is_acceptable = False
                        # Found first conflicting dependency in alphabetical order of dependency names
                        dependency_conflicts[f"DepConflict_{candidate_version}"] = f"  {next_package} {candidate_version} requires {dep_name} {dep_range}, but {dep_name} {selected_version} is selected"
                        break # Stop checking dependencies for this candidate

            if not is_acceptable:
                continue # Try next candidate

            # --- Candidate is Acceptable: Recurse ---

            # Update state for recursion
            new_selected = current_selected.copy()
            new_selected[next_package] = candidate_version
            new_log = current_log + [(next_package, candidate_version)]

            # Update order: add new, unselected dependency names alphabetically
            new_order = list(current_order)
            new_deps_to_add = []
            for dep_name in candidate_deps.keys():
                if dep_name not in current_selected and dep_name not in new_order:
                    new_deps_to_add.append(dep_name)

            new_order.extend(sorted(new_deps_to_add))

            # Recurse
            result = backtrack(new_order, new_selected, new_log)
            if result is not None:
                # Success down this path
                return result

            # --- Backtrack happens implicitly by not returning or modifying the outer scope state ---

        # 5. Failure: No candidate led to success

        # Construct the error explanation for THIS package (next_package)
        error_lines = []
        error_lines.append(f"cannot resolve {next_package}")

        # Constraints list
        for requirer, constraint_range in constraints_info:
            error_lines.append(f"  {requirer} requires {next_package} {constraint_range}")

        # Version exclusion list (only if there are known versions)
        if all_versions:
            # We must check every candidate again to see *why* it failed, matching the example logic
            for candidate_version in all_versions:
                is_excluded = False
                # Check constraint failure
                for requirer, constraint_range in constraints_info:
                    if not constraint_range.contains(candidate_version):
                        error_lines.append(f"  {next_package} {candidate_version} is excluded by the constraints")
                        is_excluded = True
                        break

                if is_excluded: continue

                # Check dependency failure
                candidate_deps = index.requirements(next_package, candidate_version)
                conflicting_dep_found = False
                for dep_name, dep_range in candidate_deps.items():
                    if dep_name in current_selected:
                        selected_version = current_selected[dep_name]
                        if not dep_range.contains(selected_version):
                            error_lines.append(f"  {next_package} {candidate_version} requires {dep_name} {dep_range}, but {dep_name} {selected_version} is selected")
                            conflicting_dep_found = True
                            break # First conflicting dependency in alphabetical order

                if conflicting_dep_found:
                    continue

                # If we reached here, the candidate *was* acceptable, but the recursion failed. 
                # According to the prompt's error description, we only list reasons for *exclusion*. 
                # If a candidate was acceptable but led to failure, the error should be attributed to the *next* step, not this one, UNLESS all candidates failed.
                # The example implies we list reasons for exclusion. If all candidates pass constraints but fail later, the error message needs clarification, but following the example structure, we only list exclusions.
                # Since we exhausted all candidates, we stop listing versions.
                pass

        explanation = "\n".join(error_lines)
        raise ResolutionError(next_package, explanation)

    # Start search
    return backtrack(order, selected, selection_log)
