from typing import Tuple

class Version:
    def __init__(self, text: str):
        parts = text.split('.')
        if len(parts) != 3:
            raise ValueError(f"Version '{text}' must have three parts (MAJOR.MINOR.PATCH).")
        try:
            self.major = int(parts[0])
            self.minor = int(parts[1])
            self.patch = int(parts[2])
        except ValueError:
            raise ValueError(f"Version parts must be integers, got '{text}'.")

        # Check for leading zeros, except for '0' itself
        for i, part_str in enumerate(parts):
            if len(part_str) > 1 and part_str.startswith('0'):
                raise ValueError(f"Version part '{part_str}' in '{text}' has invalid leading zero.")

    @property
    def major(self) -> int:
        return self._major

    @property
    def minor(self) -> int:
        return self._minor

    @property
    def patch(self) -> int:
        return self._patch

    def __init__(self, text: str):
        parts = text.split('.')
        if len(parts) != 3:
            raise ValueError(f"Version '{text}' must have three parts (MAJOR.MINOR.PATCH).")
        try:
            self._major = int(parts[0])
            self._minor = int(parts[1])
            self._patch = int(parts[2])
        except ValueError:
            raise ValueError(f"Version parts must be integers, got '{text}'.")

        # Check for leading zeros, except for '0' itself
        for i, part_str in enumerate(parts):
            if len(part_str) > 1 and part_str.startswith('0'):
                raise ValueError(f"Version part '{part_str}' in '{text}' has invalid leading zero.")

    def __lt__(self, other: 'Version') -> bool:
        return (self.major, self.minor, self.patch) < (other.major, other.minor, other.patch)

    def __le__(self, other: 'Version') -> bool:
        return (self.major, self.minor, self.patch) <= (other.major, other.minor, other.patch)

    def __gt__(self, other: 'Version') -> bool:
        return (self.major, self.minor, self.patch) > (other.major, other.minor, other.patch)

    def __ge__(self, other: 'Version') -> bool:
        return (self.major, self.minor, self.patch) >= (other.major, other.minor, other.patch)

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, Version):
            return NotImplemented
        return self.major == other.major and self.minor == other.minor and self.patch == other.patch

    def __hash__(self) -> int:
        return hash((self.major, self.minor, self.patch))

    def __str__(self) -> str:
        return f"{self.major}.{self.minor}.{self.patch}"

class Range:
    def __init__(self, spec: str):
        self.spec_str = spec.strip()
        self.constraints = self._parse_spec(spec)

    def _parse_spec(self, spec: str) -> list[tuple[str, str | None]]:
        constraints = []
        parts = [p.strip() for p in spec.split(',')]

        if not spec.strip():
            # Empty spec is invalid unless it implies '*' which isn't specified, so treat as invalid if strictly empty
            raise ValueError("Empty range spec is not allowed.")

        for part in parts:
            if not part: # Empty constraint part (e.g., '>=1.0.0,')
                raise ValueError("Empty constraint found in range specification.")

            part = part.strip()
            if part == "*":
                constraints.append(('any', None))
                continue

            # Check for operators/prefixes
            operator = None
            version_str = part

            if part.startswith('=='):
                operator = '=='
                version_str = part[2:]
            elif part.startswith('!='):
                operator = '!='
                version_str = part[2:]
            elif part.startswith('>='):
                operator = '>='
                version_str = part[2:]
            elif part.startswith('<='):
                operator = '<='
                version_str = part[2:]
            elif part.startswith('>'):
                operator = '>'
                version_str = part[1:]
            elif part.startswith('<'):
                operator = '<'
                version_str = part[1:]
            elif part.startswith('^'):
                operator = '^'
                version_str = part[1:]
            elif part.startswith('~'):
                operator = '~'
                version_str = part[1:]
            else:
                # Check for exact match without operator
                if '.' in part and all(c.isdigit() or c == '.' for c in part):
                     # If it looks like a version and no operator found, assume == (or raise if strict)
                     # Following convention, if no explicit operator, it must be a full version constraint, let's default to == for simplicity if it parses
                     # However, the spec lists '1.2.3' OR '==1.2.3'. We assume '1.2.3' implies == if no operator is present.
                     operator = '=='
                     version_str = part
                else:
                     raise ValueError(f"Unknown operator or invalid constraint part: {part}")

            if not version_str.strip():
                raise ValueError(f"Missing version for operator in constraint: {part}")

            try:
                version = Version(version_str.strip())
                constraints.append((operator, version))
            except ValueError as e:
                raise ValueError(f"Bad version in constraint '{part}': {e}")

        return constraints

    def contains(self, v: Version) -> bool:
        for op, required_v in self.constraints:
            if op == 'any':
                continue

            is_contained = False
            if op == '==':
                is_contained = (v == required_v)
            elif op == '!=':
                is_contained = (v != required_v)
            elif op == '>=':
                is_contained = (v >= required_v)
            elif op == '<=':
                is_contained = (v <= required_v)
            elif op == '>':
                is_contained = (v > required_v)
            elif op == '<':
                is_contained = (v < required_v)
            elif op == '^':
                # ^1.2.3 is >=1.2.3 and <2.0.0 (where 2 is next major component change)
                if required_v.major == 0 and required_v.minor == 0 and required_v.patch == 0:
                    # ^0.0.0 is >=0.0.0, <0.0.1
                    upper_bound = Version(f"0.0.{required_v.patch + 1}")
                elif required_v.major == 0 and required_v.minor == 0:
                    # ^0.2.3 is >=0.2.3, <0.3.0
                    upper_bound = Version(f"0.{required_v.minor + 1}.0")
                elif required_v.major == 0:
                    # ^0.2.3 is >=0.2.3, <0.1.0 (Error in spec interpretation, should be <1.0.0 if major is 0)
                    # Spec says: ^0.2.3 is >=0.2.3, <0.3.0
                    upper_bound = Version(f"0.{required_v.minor + 1}.0")
                else:
                    # ^1.2.3 is >=1.2.3, <2.0.0
                    upper_bound = Version(f"{required_v.major + 1}.0.0")

                is_contained = (v >= required_v) and (v < upper_bound)
            elif op == '~':
                # ~1.2.3 is >=1.2.3, <1.3.0 (where 3 is next minor component change)
                if required_v.patch == 0:
                    # ~1.2.0 is >=1.2.0, <1.3.0
                    upper_bound = Version(f"{required_v.major}.{required_v.minor + 1}.0")
                else:
                    # ~1.2.3 is >=1.2.3, <1.2.4
                    upper_bound = Version(f"{required_v.major}.{required_v.minor}.{required_v.patch + 1}")
                is_contained = (v >= required_v) and (v < upper_bound)

            if not is_contained:
                return False

        return True

    def __str__(self) -> str:
        # Return the spec with all whitespace removed
        return self.spec_str.replace(' ', '')

    def __repr__(self) -> str:
        return f"Range("{self.spec_str}")"

