from typing import Dict, List, Optional, TYPE_CHECKING

# Type hinting for Version and Range to avoid circular imports during runtime
if TYPE_CHECKING:
    from .versions import Version, Range
else:
    # Mock types for runtime if needed, though ideally imports handle this
    Version = object
    Range = object

class PackageIndex:
    def __init__(self):
        # Structure: {name: {version_string: {'requires': {dep_name: Range, ...}}}} 
        self._data: Dict[str, Dict[str, dict]] = {}

    def add(self, name: str, version: str, requires: Optional[Dict[str, 'Range']] = None):
        if name in self._data and version in self._data[name]:
            raise ValueError(f"Release {name} version {version} already exists in the index.")

        if requires is None:
            requires = {}

        try:
            # Validate version string immediately
            Version(version)
        except ValueError as e:
            raise ValueError(f"Invalid version string '{version}' for {name}: {e}")

        self._data.setdefault(name, {})[version] = {'requires': requires}

    def versions(self, name: str) -> List['Version']:
        if name not in self._data:
            return []

        version_strings = list(self._data[name].keys())

        # Sort versions newest first (reverse numerical order)
        def version_key(v_str): 
            try:
                v = Version(v_str)
                return (v.major, v.minor, v.patch)
            except ValueError:
                # Should not happen if add() enforces validation
                return (-1, -1, -1) 

        version_strings.sort(key=version_key, reverse=True)

        return [Version(v_str) for v_str in version_strings]

    def requirements(self, name: str, version: 'Version') -> Dict[str, 'Range']:
        if name not in self._data or version.as_str() not in self._data[name]:
            raise KeyError(f"Version {version} of package {name} not found.")

        return self._data[name][version.as_str()]['requires']

    @classmethod
    def from_dict(cls, data: Dict[str, Dict[str, dict]]):
        index = cls()
        for name, versions_data in data.items():
            for version_str, details in versions_data.items():
                # Details should contain 'requires'
                requires = details.get('requires', {}) 
                index.add(name, version_str, requires)
