        """Formats an FSError output line."""
        error_name = error_class.__name__
        return f"line {line_num}: {command}: {error_name}: {path}\n"

    def _run_command(self, line: str, line_num: int) -> Tuple[str, int]:
        """Parses and executes a single line command, returning output and status.
