        try:
            parts = shlex.split(line)
        except ValueError: 
            # Quoting error
            command = line.split()[0] if line.strip() else "UNKNOWN"
            return f"line {line_num}: {command}: usage\n", 2

        if not parts: # Should be filtered earlier, but defensive check
            return "", 0

        command_name = parts[0]
        args = parts[1:]
        output = ""
        status = 0

        try:
            if command_name == "pwd":
                output = self.fs.pwd() + "\n"

            elif command_name == "cd":
                if not args: 
                    # cd with no arguments defaults to home, which is '/' in VFS
                    self.fs.cd('/') 
                    return "", 0

                # cd only takes one argument: PATH
                try:
                    self.fs.cd(args[0])
                except NotFound as e:
                    return self._format_error(line_num, command_name, NotFound, e.path) + "", 1
                except NotADirectory as e:
                    return self._format_error(line_num, command_name, NotADirectory, e.path) + "", 1

