                    return self._format_error(line_num, command_name, NotFound, e.path) + "", 1
                except InvalidOperation as e:
                    return self._format_error(line_num, command_name, InvalidOperation, e.path) + "", 1
                except IsADirectory as e:
                    return self._format_error(line_num, command_name, IsADirectory, e.path) + "", 1

            elif command_name == "mv":
                # mv SRC DST
                if len(args) != 2:
                    return f"line {line_num}: {command_name}: usage\n", 2
                try:
                    self.fs.mv(args[0], args[1])
                except NotFound as e:
                    return self._format_error(line_num, command_name, NotFound, e.path) + "", 1
                except InvalidOperation as e:
                    return self._format_error(line_num, command_name, InvalidOperation, e.path) + "", 1
                except AlreadyExists as e:
                    return self._format_error(line_num, command_name, AlreadyExists, e.path) + "", 1
                except Exception as e: 
                    # Catch any other unforeseen FS errors
                    return self._format_error(line_num, command_name, type(e), getattr(e, 'path', '')) + "", 1

            elif command_name == "write":
                # write PATH [WORD...] (words joined by single space + \n)
                if len(args) < 1: 
                    return f"line {line_num}: {command_name}: usage\n", 2

                path = args[0]
                text = " ".join(args[1:]) + "\n"
                try:
                    self.fs.write(path, text, append=False)
                except IsADirectory as e:
                    return self._format_error(line_num, command_name, IsADirectory, e.path) + "", 1
                except NotFound as e:
                    return self._format_error(line_num, command_name, NotFound, e.path) + "", 1

            elif command_name == "append":
                # append PATH [WORD...] (appended + \n)
                if len(args) < 1: 
                    return f"line {line_num}: {command_name}: usage\n", 2

                path = args[0]
                text = " ".join(args[1:]) + "\n"
                try:
                    self.fs.write(path, text, append=True)
                except IsADirectory as e:
                    return self._format_error(line_num, command_name, IsADirectory, e.path) + "", 1
                except NotFound as e:
                    return self._format_error(line_num, command_name, NotFound, e.path) + "", 1

            elif command_name == "cat":
                # cat PATH...
                if not args: 
                    return f"line {line_num}: {command_name}: usage\n", 2

                all_cat_output = ""
                for path in args:
                    try:
                        all_cat_output += self.fs.read(path) # read returns text + \n if successful
                    except NotFound as e:
                        return self._format_error(line_num, command_name, NotFound, e.path) + "", 1
                    except IsADirectory as e:
                        return self._format_error(line_num, command_name, IsADirectory, e.path) + "", 1

                output = all_cat_output

            elif command_name == "find":
                # find [PATH] [-name PATTERN]
                path = args[0] if args else '.'
                pattern = "*"
                flag_seen = False

                if args:
                    # Check for -name flag
                    if args[0] == "-name" and len(args) > 1:
                        pattern = args[1]
                        flag_seen = True
                        args = args[0:1] + args[2:] # Reconstruct args list excluding flag/pattern pair if found
                    elif args[0] not in ('-name',): # If it's not a recognized flag, it must be the path
                        pass # Path is args[0]

                try:
                    results = self.fs.find(path, pattern)
                    output = "".join(results) + "\n"
                except NotFound as e:
                    return self._format_error(line_num, command_name, NotFound, e.path) + "", 1

            else:
                # Unknown command
                return f"line {line_num}: {command_name}: unknown command\n", 2

        except Exception as e:
             # Catch any unexpected errors not covered by specific FS error checks
             return f"line {line_num}: {command_name}: usage\n", 2

        return output, status

    def run(self, script_path: str) -> Tuple[str, int]:
        """Runs the script located at script_path and returns (output, status)."""
        output = ""
        status = 0

        try:
            with open(script_path, 'r', encoding='utf-8') as f:
                lines = f.readlines()
        except FileNotFoundError:
            # Script file cannot be read (Rule: print message to stderr and exit with 2)
            sys.stderr.write(f"error: Script file not found: {script_path}\n")
            return "", 2
        except Exception:
            sys.stderr.write(f"error: Could not read script file: {script_path}\n")
            return "", 2

        for i, raw_line in enumerate(lines):
            line_num = i + 1
            line = raw_line.strip()

            # Skip empty lines and comments
            if not line or line.startswith('#'):
                continue

            command = line.split()[0] if line.strip() else ""
            output_part, run_status = self._run_command(line, line_num)

            if run_status != 0: # Stop on any error (1 or 2)
                output += output_part
                return output, run_status

            output += output_part

        return output, 0

